/**
 * Sidebar panel: lists saved emitter profiles with search and category
 * filters. Related profiles can be grouped into collapsible folders; end users
 * see and toggle a folder as one row, while developers expand it to edit its
 * members. Authoring controls (vertex picker, edit/rename/delete, folder
 * drag-and-drop) only appear in developer mode; end users see read-only presets
 * with enable/disable toggles.
 */
class ParticlesPanel extends PluginPanel
{
	enum Category
	{
		ALL("All", false),
		PLAYER("Player", false),
		WORLD("World", false),
		GRAPHIC("Gfx", false),
		NPC("NPC", false),
		PROJECTILE("Proj", true);


		private final String label;
		/**
		 * Work-in-progress category: outside developer mode its tab shows a
		 * Coming soon placeholder, its profiles vanish from the sidebar, and
		 * they are force-disabled at emission time. Flip to false when the
		 * category is ready to ship.
		 */
		private final boolean wip;

		Category(String label, boolean wip)
		{
			this.label = label;
			this.wip = wip;
		}

		boolean matches(EmitterProfile profile)
		{
			switch (this)
			{
				case PLAYER:
					return EmitterProfile.TARGET_PLAYER.equals(profile.getTargetType());
				case PROJECTILE:
					return profile.isProjectileTarget();
				case WORLD:
					return profile.isObjectTarget();
				case NPC:
					return profile.isNpcTarget();
				case GRAPHIC:
					return profile.isGraphicTarget();
				default:
					return true;
			}
		}

		/**
		 * True when the profile is individually marked work-in-progress or
		 * falls into any WIP category, so it is hidden and force-disabled
		 * outside developer mode.
		 */
		static boolean isWip(EmitterProfile profile)
		{
			if (profile.isWip())
			{
				return true;
			}
			return categoryWip(profile);
		}

		/**
		 * True when the profile's category (not the profile itself) is WIP -
		 * used to hide a whole folder for shipped users.
		 */
		static boolean categoryWip(EmitterProfile profile)
		{
			for (Category value : values())
			{
				if (value.wip && value.matches(profile))
				{
					return true;
				}
			}
			return false;
		}
	}

	/**
	 * A profile's effective enabled state, folding in its folder's preference
	 * (the folder gates every member). Static and pure over an explicit folders
	 * map so it runs against an atomic snapshot without tearing against live
	 * store state.
	 */
	static boolean effectiveEnabled(EmitterProfile profile, Map<String, ProfileFolder> folders)
	{
		if (!profile.isEnabled())
		{
			return false;
		}
		String folderId = profile.getFolderId();
		if (folderId == null)
		{
			return true;
		}
		ProfileFolder folder = folders.get(folderId);
		return folder == null || folder.isEnabled();
	}

	/**
	 * A profile's effective WIP state: its own or its category's WIP, plus its
	 * folder's WIP (which hides the whole group for shipped users).
	 */
	static boolean effectiveWip(EmitterProfile profile, Map<String, ProfileFolder> folders)
	{
		if (Category.isWip(profile))
		{
			return true;
		}
		String folderId = profile.getFolderId();
		if (folderId == null)
		{
			return false;
		}
		ProfileFolder folder = folders.get(folderId);
		return folder != null && folder.isWip();
	}

	/**
	 * The folder mutations the sidebar fires, bundled so the constructor stays
	 * readable. create groups two loose profiles; addMember joins an existing
	 * folder; removeMember orphans one child; the rest map to the folder's own
	 * settings.
	 */
	static final class FolderActions
	{
		final BiConsumer<String, Boolean> toggleEnabled;
		final BiConsumer<String, Boolean> toggleWip;
		final Consumer<String> rename;
		final Consumer<String> dissolve;
		final Consumer<String> removeMember;
		final BiConsumer<String, String> create;
		final BiConsumer<String, String> addMember;

		FolderActions(BiConsumer<String, Boolean> toggleEnabled, BiConsumer<String, Boolean> toggleWip,
			Consumer<String> rename, Consumer<String> dissolve, Consumer<String> removeMember,
			BiConsumer<String, String> create, BiConsumer<String, String> addMember)
		{
			this.toggleEnabled = toggleEnabled;
			this.toggleWip = toggleWip;
			this.rename = rename;
			this.dissolve = dissolve;
			this.removeMember = removeMember;
			this.create = create;
			this.addMember = addMember;
		}
	}

	/**
	 * Bulk enable/disable over the rendered rows: loose profile keys and folder
	 * ids handled separately (foldered children are never touched).
	 */
	interface BulkToggle
	{
		void accept(Set<String> looseKeys, Set<String> folderIds, boolean enabled);
	}

	/**
	 * Dev-only ship/WIP mark icons: a red check for shipped, an empty box for
	 * work-in-progress. Drawn so the check is red regardless of the theme.
	 */
	private static final Icon PUBLISHED_ICON = markIcon(true);
	private static final Icon WIP_ICON = markIcon(false);

	// Client-property keys stashed on rows so a drop reads identity off the
	// live component under the cursor, never a stale rebuilt row reference.
	private static final String DRAG_KEY = "particles.dragKey";
	private static final String DRAG_CAT = "particles.dragCat";
	private static final String DROP_KIND = "particles.dropKind";
	private static final String DROP_KEY = "particles.dropKey";
	private static final String DROP_CAT = "particles.dropCat";
	private static final String DROP_FOLDER = "particles.dropFolder";
	private static final int DRAG_THRESHOLD = 5;

	private final boolean developerMode;
	private final BiConsumer<String, Boolean> onToggleProfile;
	private final BiConsumer<String, Boolean> onToggleWip;
	private final BulkToggle onToggleMany;
	private final BiConsumer<String, EmitterProfile> onPasteStyle;
	private final Consumer<String> onDeleteProfile;
	private final Consumer<String> onRenameProfile;
	private final Consumer<String> onEditProfile;
	private final FolderActions folderActions;
	private final JPanel profileList = new JPanel();
	private final IconTextField searchBar = new IconTextField();

	private Category category = Category.ALL;
	private Map<String, EmitterProfile> profiles = Map.of();
	private Map<String, ProfileFolder> folders = Map.of();
	private Set<String> presentSignatures = Set.of();
	/**
	 * Folder ids the developer has expanded; kept across re-renders so editing
	 * a child doesn't collapse the folder.
	 */
	private final Set<String> expanded = new HashSet<>();
	/**
	 * Style clipboard for the right-click copy/paste flow; a detached copy
	 * so later edits or deletion of the source don't change what pastes.
	 */
	@Nullable
	private EmitterProfile copiedStyle;

	// Drag state lives on the panel, not on rows (rows are rebuilt each render)
	@Nullable
	private String dragKey;
	@Nullable
	private String dragCategory;
	@Nullable
	private Point pressScreen;
	private boolean dragging;
	private boolean pendingRender;
	@Nullable
	private JComponent dropTarget;
	@Nullable
	private Border dropTargetBorder;

	/**
	 * One shared recognizer attached to every drag handle; it reads the dragged
	 * profile's identity off the handle's client properties at press time.
	 */
	private final MouseAdapter dragAdapter = new MouseAdapter()
	{
		@Override
		public void mousePressed(MouseEvent e)
		{
			JComponent handle = (JComponent) e.getComponent();
			dragKey = (String) handle.getClientProperty(DRAG_KEY);
			dragCategory = (String) handle.getClientProperty(DRAG_CAT);
			pressScreen = e.getLocationOnScreen();
			dragging = false;
		}

		@Override
		public void mouseDragged(MouseEvent e)
		{
			if (dragKey == null)
			{
				return;
			}
			if (!dragging)
			{
				Point now = e.getLocationOnScreen();
				if (Math.hypot(now.x - pressScreen.x, now.y - pressScreen.y) < DRAG_THRESHOLD)
				{
					return;
				}
				dragging = true;
			}
			hoverDropTarget(e);
		}

		@Override
		public void mouseReleased(MouseEvent e)
		{
			boolean wasDragging = dragging;
			dragging = false;
			if (wasDragging)
			{
				performDrop(e);
			}
			dragKey = null;
			dragCategory = null;
			clearHighlight();
			if (pendingRender)
			{
				pendingRender = false;
				render();
			}
		}
	};

	ParticlesPanel(boolean developerMode, Runnable openViewer, Runnable onExport,
		BiConsumer<String, Boolean> onToggleProfile,
		BiConsumer<String, Boolean> onToggleWip, BulkToggle onToggleMany,
		BiConsumer<String, EmitterProfile> onPasteStyle, Consumer<String> onDeleteProfile,
		Consumer<String> onRenameProfile, Consumer<String> onEditProfile, FolderActions folderActions)
	{
		this.developerMode = developerMode;
		this.onToggleProfile = onToggleProfile;
		this.onToggleWip = onToggleWip;
		this.onToggleMany = onToggleMany;
		this.onPasteStyle = onPasteStyle;
		this.onDeleteProfile = onDeleteProfile;
		this.onRenameProfile = onRenameProfile;
		this.onEditProfile = onEditProfile;
		this.folderActions = folderActions;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		profileList.setLayout(new BoxLayout(profileList, BoxLayout.Y_AXIS));

		JButton support = new JButton(new ImageIcon(ImageUtil.loadImageResource(ParticlesPlugin.class, "/support.png")));
		support.setToolTipText("Thank you! <3");
		support.addActionListener(e -> LinkBrowser.browse("https://buymeacoffee.com/cnnnr"));

		JButton enableAll = new JButton("Enable all");
		enableAll.setToolTipText("Turn on every preset in the selected tab");
		enableAll.addActionListener(e -> onToggleMany.accept(looseKeysInTab(), folderIdsInTab(), true));

		JButton disableAll = new JButton("Disable all");
		disableAll.setToolTipText("Turn off every preset in the selected tab");
		disableAll.addActionListener(e -> onToggleMany.accept(looseKeysInTab(), folderIdsInTab(), false));

		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));

		searchBar.setIcon(IconTextField.Icon.SEARCH);
		// IconTextField paints no background until its focus/hover listeners
		// first fire; give it one up front like the core plugin panels do
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchBar.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				render();
			}
		});
		searchBar.addClearListener(this::render);

		// Search takes three quarters of the top row, the support heart the rest
		JPanel topRow = new JPanel(new GridBagLayout());
		GridBagConstraints gbc = new GridBagConstraints();
		gbc.fill = GridBagConstraints.BOTH;
		gbc.weighty = 1;
		gbc.weightx = 0.75;
		topRow.add(searchBar, gbc);
		gbc.weightx = 0.25;
		gbc.insets = new Insets(0, 4, 0, 0);
		topRow.add(support, gbc);
		topRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		controls.add(topRow);
		controls.add(Box.createVerticalStrut(6));

		if (developerMode)
		{
			JButton open = new JButton("Vertex picker");
			open.addActionListener(e -> openViewer.run());
			JButton export = new JButton("Export bundle");
			export.setToolTipText("Mirror the current profiles and folders into presets.json + folders.json");
			export.addActionListener(e -> onExport.run());
			JPanel openRow = new JPanel(new GridLayout(1, 2, 4, 0));
			openRow.add(open);
			openRow.add(export);
			openRow.setAlignmentX(Component.LEFT_ALIGNMENT);
			controls.add(openRow);
			controls.add(Box.createVerticalStrut(6));
		}

		MaterialTabGroup tabGroup = new MaterialTabGroup();
		// Three equal tabs per row, wrapping like the button grid above
		tabGroup.setLayout(new GridLayout(0, 3, 4, 4));
		for (Category value : Category.values())
		{
			MaterialTab tab = new MaterialTab(value.label, tabGroup, new JPanel());
			tab.setHorizontalAlignment(SwingConstants.CENTER);
			tab.setOnSelectEvent(() ->
			{
				category = value;
				render();
				return true;
			});
			tabGroup.addTab(tab);
			if (value == Category.ALL)
			{
				tabGroup.select(tab);
			}
		}
		tabGroup.setAlignmentX(Component.LEFT_ALIGNMENT);
		controls.add(tabGroup);
		controls.add(Box.createVerticalStrut(6));

		JPanel bulkRow = new JPanel(new GridLayout(1, 2, 4, 0));
		bulkRow.add(enableAll);
		bulkRow.add(disableAll);
		bulkRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		controls.add(bulkRow);

		JPanel north = new JPanel(new BorderLayout(0, 8));
		north.add(controls, BorderLayout.NORTH);
		add(north, BorderLayout.NORTH);
		add(profileList, BorderLayout.CENTER);

		// Under the profile list: a link to the hub page's suggestions
		JLabel suggest = new JLabel("<html>Learn how to submit suggestions <u>here</u></html>");
		suggest.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		suggest.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		suggest.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		suggest.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse("https://runelite.net/plugin-hub/show/particles");
			}
		});
		add(suggest, BorderLayout.SOUTH);
	}

	/**
	 * Loose (ungrouped) profile keys the current tab shows, for the bulk
	 * buttons. Foldered children are excluded - the folder is bulk-toggled.
	 */
	private Set<String> looseKeysInTab()
	{
		Set<String> keys = new HashSet<>();
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.getFolderId() == null && category.matches(profile)
				&& (developerMode || !Category.isWip(profile)))
			{
				keys.add(entry.getKey());
			}
		}
		return keys;
	}

	/**
	 * Folder ids the current tab shows, for the bulk buttons.
	 */
	private Set<String> folderIdsInTab()
	{
		Set<String> ids = new HashSet<>();
		for (ProfileFolder folder : folders.values())
		{
			EmitterProfile rep = representativeOf(folder.getId());
			if (rep != null && category.matches(rep)
				&& (developerMode || !(folder.isWip() || Category.categoryWip(rep))))
			{
				ids.add(folder.getId());
			}
		}
		return ids;
	}

	/**
	 * Update the profile and folder data and re-render. Must be called on the
	 * Swing EDT.
	 *
	 * @param presentSignatures signatures of pieces on the currently worn model
	 */
	void rebuild(Map<String, EmitterProfile> profiles, Map<String, ProfileFolder> folders,
		Set<String> presentSignatures)
	{
		this.profiles = profiles;
		this.folders = folders;
		this.presentSignatures = presentSignatures;
		render();
	}

	/**
	 * Re-render the list through the current category tab and search text.
	 * Suppressed while a drag is in flight so rows aren't rebuilt out from
	 * under the gesture; the deferred render runs when the drag ends.
	 */
	private void render()
	{
		if (dragging)
		{
			pendingRender = true;
			return;
		}
		profileList.removeAll();

		if (!developerMode && category.wip)
		{
			JLabel comingSoon = new JLabel("Coming soon!");
			comingSoon.setForeground(Color.GRAY);
			comingSoon.setAlignmentX(Component.LEFT_ALIGNMENT);
			profileList.add(comingSoon);
			profileList.revalidate();
			profileList.repaint();
			return;
		}

		String query = searchBar.getText() == null ? "" : searchBar.getText().trim().toLowerCase();
		List<Item> items = new ArrayList<>();

		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.getFolderId() != null || !category.matches(profile)
				|| (!developerMode && Category.isWip(profile)) || !matchesSearch(profile, query))
			{
				continue;
			}
			items.add(Item.profile(entry.getKey(), profile));
		}

		for (ProfileFolder folder : folders.values())
		{
			EmitterProfile rep = representativeOf(folder.getId());
			if (rep == null || !category.matches(rep)
				|| (!developerMode && (folder.isWip() || Category.categoryWip(rep)))
				|| !folderMatchesSearch(folder, query))
			{
				continue;
			}
			items.add(Item.folder(folder));
		}

		Comparator<Item> byName = Comparator.comparing(item -> item.name == null ? "" : item.name.toLowerCase());
		// Developers author folders, so group them ahead of loose profiles;
		// end users see identical rows, so keep them interleaved alphabetically
		items.sort(developerMode
			? Comparator.<Item>comparingInt(item -> item.folder ? 0 : 1).thenComparing(byName)
			: byName);

		if (!items.isEmpty())
		{
			String count = items.size() + (items.size() == 1 ? " item" : " items");
			if (developerMode && category.wip)
			{
				count += " (WIP category)";
			}
			JLabel header = new JLabel(count);
			header.setAlignmentX(Component.LEFT_ALIGNMENT);
			profileList.add(header);
			profileList.add(Box.createVerticalStrut(6));
		}

		for (Item item : items)
		{
			profileList.add(item.folder
				? buildFolderRow(item.folderObj, query)
				: buildRow(item.key, item.profile));
		}

		profileList.revalidate();
		profileList.repaint();
	}

	private JPanel buildRow(String profileKey, EmitterProfile profile)
	{
		boolean inFolder = profile.getFolderId() != null;
		// Signature presence only means worn for player profiles; trivial
		// fragment signatures collide across unrelated models
		boolean worn = EmitterProfile.TARGET_PLAYER.equals(profile.getTargetType())
			&& presentSignatures.contains(profile.getSignature());
		String text = profile.getName()
			+ (profile.isProjectileTarget() && developerMode ? " [proj " + profile.getProjectileId() + "]" : "")
			+ (profile.isObjectTarget() && developerMode ? " [obj " + profile.getObjectId() + "]" : "")
			+ (profile.isNpcTarget() && developerMode ? " [npc " + profile.getNpcId() + "]" : "")
			+ (profile.isGraphicTarget() && developerMode ? " [gfx " + profile.getGraphicId() + "]" : "");

		JCheckBox toggle = new JCheckBox(text, profile.isEnabled());
		// Rows truncate in the narrow sidebar; the tooltip carries the full
		// name and tag, plus the worn state where that concept applies
		toggle.setToolTipText(EmitterProfile.TARGET_PLAYER.equals(profile.getTargetType())
			? "<html>" + text + "<br>" + (worn
				? "On the model you are wearing now"
				: "Not on your current model") + "</html>"
			: text);
		toggle.addActionListener(e -> onToggleProfile.accept(profileKey, toggle.isSelected()));

		JPanel row = new JPanel(new BorderLayout());
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(toggle, BorderLayout.CENTER);

		// Drop metadata: dropping onto a loose profile groups the two; onto a
		// child joins that child's folder
		row.putClientProperty(DROP_KIND, inFolder ? "child" : "loose");
		row.putClientProperty(DROP_KEY, profileKey);
		row.putClientProperty(DROP_CAT, profile.getTargetType());
		if (inFolder)
		{
			row.putClientProperty(DROP_FOLDER, profile.getFolderId());
		}

		if (developerMode)
		{
			JPanel west = new JPanel();
			west.setLayout(new BoxLayout(west, BoxLayout.X_AXIS));
			west.add(dragHandle(profileKey, profile.getTargetType()));

			// A ship/work-in-progress mark: a red check means shipped, unchecked
			// marks it WIP so it stays saved but vanishes for shipped users
			JCheckBox wipMark = new JCheckBox();
			wipMark.setIcon(WIP_ICON);
			wipMark.setSelectedIcon(PUBLISHED_ICON);
			wipMark.setSelected(!profile.isWip());
			wipMark.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 6));
			wipMark.setToolTipText("Ship this profile. Uncheck to mark it work-in-progress: it stays saved but is hidden and disabled for non-developer users.");
			wipMark.addActionListener(e -> onToggleWip.accept(profileKey, !wipMark.isSelected()));
			west.add(wipMark);
			row.add(west, BorderLayout.WEST);

			JButton edit = new JButton("e");
			edit.setMargin(new Insets(0, 4, 0, 4));
			edit.setToolTipText("Edit this profile in the vertex picker");
			edit.addActionListener(e -> onEditProfile.accept(profileKey));

			JButton rename = new JButton("~");
			rename.setMargin(new Insets(0, 4, 0, 4));
			rename.setToolTipText("Rename this profile");
			rename.addActionListener(e -> onRenameProfile.accept(profileKey));

			JButton delete = new JButton("x");
			delete.setMargin(new Insets(0, 4, 0, 4));
			delete.setToolTipText("Delete this profile");
			delete.addActionListener(e -> onDeleteProfile.accept(profileKey));

			JPanel buttons = new JPanel();
			buttons.setLayout(new BoxLayout(buttons, BoxLayout.X_AXIS));
			buttons.add(edit);
			buttons.add(rename);
			buttons.add(delete);
			row.add(buttons, BorderLayout.EAST);

			JPopupMenu menu = new JPopupMenu();
			JMenuItem copyStyle = new JMenuItem("Copy style");
			copyStyle.addActionListener(e -> copiedStyle = profile.copy());
			JMenuItem pasteStyle = new JMenuItem("Paste style");
			pasteStyle.addActionListener(e ->
			{
				if (copiedStyle != null)
				{
					onPasteStyle.accept(profileKey, copiedStyle);
				}
			});
			menu.add(copyStyle);
			menu.add(pasteStyle);
			if (inFolder)
			{
				JMenuItem removeFromFolder = new JMenuItem("Remove from folder");
				removeFromFolder.addActionListener(e -> folderActions.removeMember.accept(profileKey));
				menu.add(removeFromFolder);
			}
			menu.addPopupMenuListener(new PopupMenuListener()
			{
				@Override
				public void popupMenuWillBecomeVisible(PopupMenuEvent e)
				{
					pasteStyle.setEnabled(copiedStyle != null);
				}

				@Override
				public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
				{
				}

				@Override
				public void popupMenuCanceled(PopupMenuEvent e)
				{
				}
			});
			row.setComponentPopupMenu(menu);
			toggle.setComponentPopupMenu(menu);
		}

		if (inFolder)
		{
			row.setBorder(BorderFactory.createEmptyBorder(0, 16, 0, 0));
		}
		return row;
	}

	/**
	 * A folder row: for shipped users a single enable toggle indistinguishable
	 * from a profile row; for developers a header (WIP mark, enable toggle,
	 * expand, rename, delete, Dissolve) that expands to reveal member rows.
	 */
	private JPanel buildFolderRow(ProfileFolder folder, String query)
	{
		String folderId = folder.getId();
		if (!developerMode)
		{
			String label = folder.getName() + " (" + childrenOf(folderId).size() + ")";
			JCheckBox toggle = new JCheckBox(label, folder.isEnabled());
			toggle.setToolTipText(label);
			toggle.addActionListener(e -> folderActions.toggleEnabled.accept(folderId, toggle.isSelected()));
			JPanel row = new JPanel(new BorderLayout());
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(toggle, BorderLayout.CENTER);
			return row;
		}

		EmitterProfile rep = representativeOf(folderId);
		String cat = rep == null ? "" : rep.getTargetType();

		List<Map.Entry<String, EmitterProfile>> children = childrenOf(folderId);
		boolean searching = !query.isEmpty();
		boolean anyChildMatch = false;
		for (Map.Entry<String, EmitterProfile> child : children)
		{
			if (matchesSearch(child.getValue(), query))
			{
				anyChildMatch = true;
				break;
			}
		}
		boolean showChildren = searching ? anyChildMatch : expanded.contains(folderId);

		JPanel header = new JPanel(new BorderLayout());
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.putClientProperty(DROP_KIND, "folder");
		header.putClientProperty(DROP_KEY, folderId);
		header.putClientProperty(DROP_CAT, cat);
		header.putClientProperty(DROP_FOLDER, folderId);

		// WIP mark then enable toggle, matching the order on profile rows so the
		// red marks and preference checks line up into uniform columns
		JPanel west = new JPanel();
		west.setLayout(new BoxLayout(west, BoxLayout.X_AXIS));
		JCheckBox wipMark = new JCheckBox();
		wipMark.setIcon(WIP_ICON);
		wipMark.setSelectedIcon(PUBLISHED_ICON);
		wipMark.setSelected(!folder.isWip());
		wipMark.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 6));
		wipMark.setToolTipText("Ship this folder. Uncheck to mark the whole group work-in-progress.");
		wipMark.addActionListener(e -> folderActions.toggleWip.accept(folderId, !wipMark.isSelected()));
		west.add(wipMark);
		JCheckBox enable = new JCheckBox();
		enable.setSelected(folder.isEnabled());
		enable.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 6));
		enable.setToolTipText("Folder enabled - gates every member");
		enable.addActionListener(e -> folderActions.toggleEnabled.accept(folderId, enable.isSelected()));
		west.add(enable);
		header.add(west, BorderLayout.WEST);

		JLabel name = new JLabel((showChildren ? "▼ " : "▶ ") + folder.getName()
			+ "  (" + children.size() + ")");
		name.setToolTipText("Click to " + (showChildren ? "collapse" : "expand") + " this folder");
		name.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		name.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (expanded.contains(folderId))
				{
					expanded.remove(folderId);
				}
				else
				{
					expanded.add(folderId);
				}
				render();
			}
		});
		header.add(name, BorderLayout.CENTER);

		JButton rename = new JButton("~");
		rename.setMargin(new Insets(0, 4, 0, 4));
		rename.setToolTipText("Rename this folder");
		rename.addActionListener(e -> folderActions.rename.accept(folderId));
		JButton delete = new JButton("x");
		delete.setMargin(new Insets(0, 4, 0, 4));
		delete.setToolTipText("Dissolve this folder (members return to loose rows)");
		delete.addActionListener(e -> folderActions.dissolve.accept(folderId));
		JPanel buttons = new JPanel();
		buttons.setLayout(new BoxLayout(buttons, BoxLayout.X_AXIS));
		buttons.add(rename);
		buttons.add(delete);
		header.add(buttons, BorderLayout.EAST);

		JPopupMenu menu = new JPopupMenu();
		JMenuItem dissolve = new JMenuItem("Dissolve folder");
		dissolve.addActionListener(e -> folderActions.dissolve.accept(folderId));
		menu.add(dissolve);
		header.setComponentPopupMenu(menu);
		name.setComponentPopupMenu(menu);

		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setAlignmentX(Component.LEFT_ALIGNMENT);
		container.add(header);
		if (showChildren)
		{
			children.sort(Comparator.comparing(entry ->
				entry.getValue().getName() == null ? "" : entry.getValue().getName().toLowerCase()));
			for (Map.Entry<String, EmitterProfile> child : children)
			{
				if (searching && !matchesSearch(child.getValue(), query))
				{
					continue;
				}
				container.add(buildRow(child.getKey(), child.getValue()));
			}
		}
		return container;
	}

	// --- Folder helpers ------------------------------------------------------

	private List<Map.Entry<String, EmitterProfile>> childrenOf(String folderId)
	{
		List<Map.Entry<String, EmitterProfile>> children = new ArrayList<>();
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			if (folderId.equals(entry.getValue().getFolderId()))
			{
				children.add(entry);
			}
		}
		return children;
	}

	@Nullable
	private EmitterProfile representativeOf(String folderId)
	{
		for (EmitterProfile profile : profiles.values())
		{
			if (folderId.equals(profile.getFolderId()))
			{
				return profile;
			}
		}
		return null;
	}

	private boolean folderMatchesSearch(ProfileFolder folder, String query)
	{
		if (query.isEmpty())
		{
			return true;
		}
		if (folder.getName() != null && folder.getName().toLowerCase().contains(query))
		{
			return true;
		}
		for (Map.Entry<String, EmitterProfile> child : childrenOf(folder.getId()))
		{
			if (matchesSearch(child.getValue(), query))
			{
				return true;
			}
		}
		return false;
	}

	// --- Drag and drop -------------------------------------------------------

	private JLabel dragHandle(String key, String targetType)
	{
		JLabel handle = new JLabel("≡");
		handle.setToolTipText("Drag onto another profile or a folder to group them");
		handle.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
		handle.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 6));
		handle.putClientProperty(DRAG_KEY, key);
		handle.putClientProperty(DRAG_CAT, targetType);
		handle.addMouseListener(dragAdapter);
		handle.addMouseMotionListener(dragAdapter);
		return handle;
	}

	@Nullable
	private JComponent dropTargetAt(MouseEvent e)
	{
		Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), profileList);
		Component c = SwingUtilities.getDeepestComponentAt(profileList, p.x, p.y);
		while (c != null && !(c instanceof JComponent && ((JComponent) c).getClientProperty(DROP_KIND) != null))
		{
			c = c.getParent();
		}
		return (JComponent) c;
	}

	private void hoverDropTarget(MouseEvent e)
	{
		JComponent target = dropTargetAt(e);
		highlight(target, target != null && isValidDrop(target));
	}

	private boolean isValidDrop(JComponent target)
	{
		if (dragKey == null || dragCategory == null
			|| !dragCategory.equals(target.getClientProperty(DROP_CAT)))
		{
			return false;
		}
		// Dropping a profile onto itself, or onto its own folder, is a no-op
		if ("loose".equals(target.getClientProperty(DROP_KIND)))
		{
			return !dragKey.equals(target.getClientProperty(DROP_KEY));
		}
		return true;
	}

	private void performDrop(MouseEvent e)
	{
		JComponent target = dropTargetAt(e);
		if (target == null || !isValidDrop(target))
		{
			return;
		}
		String kind = (String) target.getClientProperty(DROP_KIND);
		if ("loose".equals(kind))
		{
			folderActions.create.accept((String) target.getClientProperty(DROP_KEY), dragKey);
		}
		else if ("folder".equals(kind))
		{
			folderActions.addMember.accept((String) target.getClientProperty(DROP_KEY), dragKey);
		}
		else if ("child".equals(kind))
		{
			folderActions.addMember.accept((String) target.getClientProperty(DROP_FOLDER), dragKey);
		}
	}

	private void highlight(@Nullable JComponent target, boolean valid)
	{
		if (target == dropTarget)
		{
			return;
		}
		clearHighlight();
		if (target != null)
		{
			dropTarget = target;
			dropTargetBorder = target.getBorder();
			target.setBorder(BorderFactory.createLineBorder(
				valid ? new Color(80, 180, 80) : new Color(180, 80, 80), 2));
		}
	}

	private void clearHighlight()
	{
		if (dropTarget != null)
		{
			dropTarget.setBorder(dropTargetBorder);
			dropTarget = null;
			dropTargetBorder = null;
		}
	}

	/**
	 * One rendered row: a loose/child profile or a folder, sorted together.
	 */
	private static final class Item
	{
		final String name;
		final String key;
		final boolean folder;
		final EmitterProfile profile;
		final ProfileFolder folderObj;

		private Item(String name, String key, boolean folder, EmitterProfile profile, ProfileFolder folderObj)
		{
			this.name = name;
			this.key = key;
			this.folder = folder;
			this.profile = profile;
			this.folderObj = folderObj;
		}

		static Item profile(String key, EmitterProfile profile)
		{
			return new Item(profile.getName(), key, false, profile, null);
		}

		static Item folder(ProfileFolder folder)
		{
			return new Item(folder.getName(), folder.getId(), true, null, folder);
		}
	}

	/**
	 * A 14px checkbox glyph: a grey box, plus a red check when published.
	 */
	private static Icon markIcon(boolean published)
	{
		int s = 14;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(110, 110, 110));
		g.drawRect(1, 1, s - 3, s - 3);
		if (published)
		{
			g.setColor(new Color(220, 45, 45));
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(3, 7, 6, 10);
			g.drawLine(6, 10, 11, 3);
		}
		g.dispose();
		return new ImageIcon(img);
	}

	private static boolean matchesSearch(EmitterProfile profile, String query)
	{
		if (query.isEmpty())
		{
			return true;
		}
		if (profile.getName() != null && profile.getName().toLowerCase().contains(query))
		{
			return true;
		}
		if (profile.isProjectileTarget() && String.valueOf(profile.getProjectileId()).contains(query))
		{
			return true;
		}
		if (profile.isObjectTarget() && String.valueOf(profile.getObjectId()).contains(query))
		{
			return true;
		}
		if (profile.isNpcTarget() && String.valueOf(profile.getNpcId()).contains(query))
		{
			return true;
		}
		if (profile.isGraphicTarget() && String.valueOf(profile.getGraphicId()).contains(query))
		{
			return true;
		}
		for (int id : profile.getItemIds())
		{
			if (String.valueOf(id).contains(query))
			{
				return true;
			}
		}
		for (int id : profile.getAnimationIds())
		{
			if (String.valueOf(id).contains(query))
			{
				return true;
			}
		}
		return false;
	}
}

package dev.cnnnr;

import java.util.HashSet;
import java.util.Set;
import lombok.Getter;
import lombok.Setter;

/**
 * A saved set of emitter vertices plus particle style for one mesh piece,
 * identified by its topology signature. Vertices are piece-local indices
 * (rank within the piece), not global composite-model indices.
 */
@Getter
@Setter
class EmitterProfile
{
	static final String TARGET_PLAYER = "player";
	static final String TARGET_PROJECTILE = "projectile";
	static final String TARGET_OBJECT = "object";
	static final String TARGET_NPC = "npc";
	static final String TARGET_GRAPHIC = "graphic";

	private String name;
	/**
	 * What this profile emits from: a player model piece or a projectile.
	 */
	private String targetType = TARGET_PLAYER;
	/**
	 * Projectile (graphic) ID for projectile profiles; -1 otherwise.
	 */
	private int projectileId = -1;
	/**
	 * Scenery object ID for object profiles; -1 otherwise. Object profiles
	 * also carry a piece signature and vertices - the ID says which object,
	 * the signature says which piece of its model.
	 */
	private int objectId = -1;
	/**
	 * NPC ID for NPC profiles; -1 otherwise. Like objects: ID plus piece
	 * signature plus vertices.
	 */
	private int npcId = -1;
	/**
	 * Spot anim / graphics object ID for graphic profiles; -1 otherwise.
	 * Point-based: emits at any graphics object with this ID and on any
	 * actor playing it as a spot anim. No vertices.
	 */
	private int graphicId = -1;
	/**
	 * Topology signature of the mesh piece this profile attaches to. Multiple
	 * profiles may share a signature (e.g. one per recolored item variant).
	 * Null for non-player targets.
	 */
	private String signature;
	private boolean enabled = true;
	/**
	 * Author's work-in-progress mark: the profile stays saved but is hidden and
	 * force-disabled for shipped (non-developer) users, like a WIP category but
	 * per profile. Defaults false (shippable), so existing profiles and presets
	 * ship normally without a migration.
	 */
	private boolean wip = false;
	/**
	 * Id of the {@link ProfileFolder} this profile belongs to, or null when
	 * ungrouped. Folder membership; the folder's own settings live on the
	 * folder. Absent in old configs deserializes to null (ungrouped).
	 */
	private String folderId = null;
	private Set<Integer> vertices = new HashSet<>();
	/**
	 * Item IDs gating this profile: only active while one of these items is
	 * worn. Empty = active on any item with this mesh. Distinguishes recolored
	 * variants that share the same model.
	 */
	private Set<Integer> itemIds = new HashSet<>();
	/**
	 * Animation IDs gating this profile: only emit while the player's action
	 * or pose animation is one of these. Empty = no animation gate. Combines
	 * with the item gate (both must pass).
	 */
	private Set<Integer> animationIds = new HashSet<>();
	/**
	 * Optional frame windows within a matched action animation, e.g.
	 * "9-13, 15-19" or "7"; blank = all frames. Ignored for pose animation
	 * matches.
	 */
	private String animFrames = "";
	/**
	 * Legacy single frame window, migrated into {@link #animFrames} on load.
	 */
	private int animFrameStart = -1;
	private int animFrameEnd = -1;

	// Particle style, editable per piece in the vertex picker
	/**
	 * Particle color as ARGB; alpha is the peak opacity of the life envelope.
	 */
	private int color = 0x96FF981F;
	/**
	 * Opt-in for colour-over-life. Off by default so a profile is a single
	 * constant colour unless the author explicitly enables the end colour.
	 */
	private boolean colorFade = false;
	/**
	 * End color as ARGB for colour-over-life: while {@link #colorFade} is on,
	 * particles fade from {@link #color} to this by death (fire cooling, magic
	 * settling). The RGB is interpolated; it shares the start's peak opacity.
	 */
	private int colorEnd = 0x96FF981F;
	/**
	 * Life percent at which the fade to {@link #colorEnd} begins: the colour
	 * holds at {@link #color} until here, then ramps to the end by death.
	 * 0 fades across the whole life; higher delays the shift to late in life.
	 */
	private int colorFadeStart = 0;
	/**
	 * Particle silhouette, baked as a per-face alpha mask over the shared
	 * disc geometry. Null on profiles saved before shapes existed, migrated
	 * to DEFAULT on load.
	 */
	private Shape shape = Shape.DEFAULT;
	/**
	 * Particle diameter in local units (a tile is 128).
	 */
	private int size = 6;
	/**
	 * Per-particle random size spread in local units around {@link #size}
	 * (0 = every particle the base size). Each particle draws a size in
	 * [size - sizeJitter, size + sizeJitter], floored at 2 (the minimum
	 * particle size). Realized as the low/base/high pre-baked size variants.
	 */
	private int sizeJitter = 0;
	private int particlesPerSecond = 24;
	/**
	 * Particles per tile of emitter movement, spread evenly along each
	 * anchor's path since the last tick. Spatially uniform emission for
	 * ribbon-like weapon trails; 0 = off. Combine with rate 0 for a pure
	 * trail that only emits while the anchor moves.
	 */
	private int trailDensity = 0;
	private int lifetimeMs = 600;
	/**
	 * Upward drift in local units per second.
	 */
	private int riseSpeed = 12;
	/**
	 * Horizontal drift and wobble speed in local units per second.
	 */
	private int spreadSpeed = 6;
	/**
	 * Downward acceleration in local units per second squared; 0 = constant
	 * velocity. Turns drift into falling: drops start slow and speed up, the
	 * signature of a blood or water drip.
	 */
	private int gravity = 0;
	/**
	 * Steady wind that carries every particle, in local units per second. X is
	 * east (+) / west (-), Y is north (+) / south (-), Z is up (+) / down (-).
	 * World-aligned, so it blows the same compass direction no matter which way
	 * the wearer faces. Leaning flames, drifting smoke, blowing snow, updrafts.
	 */
	private int windX = 0;
	private int windY = 0;
	private int windZ = 0;
	/**
	 * Air resistance: each particle sheds this percent of its own velocity per
	 * second, so rises, spreads, and falls settle over life instead of coasting
	 * forever (0 = none). Paired with gravity it yields a terminal fall speed.
	 */
	private int drag = 0;
	/**
	 * Radial velocity away from (+) or toward (-) the emitter's vertex centroid,
	 * in local units per second (0 = none). Positive blows particles outward
	 * like a burst; negative sucks them toward the centre like an implosion.
	 * Applies to vertex-ring emitters; single-point targets have no centre.
	 */
	private int vortex = 0;
	/**
	 * Scales the emitter's vertices about their centroid before emitting, as a
	 * percent (100 = unchanged). Below 100 draws the emit points together,
	 * above 100 pushes them apart - like scaling/fattening vertices in a mesh
	 * editor. Applies to vertex-ring emitters; no effect on single-point ones.
	 */
	private int emitScale = 100;
	/**
	 * Elongate the particle this percent along its screen-projected velocity
	 * (0 = round). Makes fast drops read as falling streaks. Auto-capped so
	 * the stretched billboard stays inside the render bounds.
	 */
	private int stretch = 0;
	/**
	 * How much of the particle's life it holds its round shape before
	 * stretching to the full amount (0 = stretched the whole time; 100 =
	 * starts round and elongates late, like a droplet letting go). The ramp
	 * is late-biased over the remaining life.
	 */
	private int stretchRamp = 0;
	/**
	 * Random spawn offset around the emitter vertex in local units.
	 */
	private int spawnJitter = 6;
	/**
	 * Feathered emission strength: spawn along a line chained through the
	 * emitter vertices, smoothed by averaging each point over this many
	 * neighbors to either side. 0 = off, 1 = light rounding, higher values
	 * cut across jagged notches into a soft continuous band.
	 */
	private int featherStrength = 0;
	/**
	 * Extra emitter points inserted between each pair of mesh-adjacent
	 * picked vertices (1 roughly doubles the emitter count). Densifies
	 * emission on low-poly meshes without feathering's smoothing.
	 */
	private int interpolation = 0;
	/**
	 * Nudge particles this many local units toward the camera at render
	 * time. Garment faces that win by render priority (a cape over a skirt)
	 * would otherwise swallow particles by plain depth; a small bias lets
	 * particles ride on top the way their host piece does.
	 */
	private int depthBias = 0;
	/**
	 * Percent of normal particle lifetime while the wearer's walk or run
	 * pose animation is playing (10-100). Shortening it keeps fast-moving
	 * plumes tight instead of smearing a tile behind the player.
	 */
	private int movementLifetime = 100;
	/**
	 * Legacy flag, migrated into {@link #movementLifetime} on load.
	 */
	private boolean dynamicLifetime = false;
	/**
	 * Legacy on/off flag, migrated into {@link #featherStrength} on load.
	 */
	private boolean feather = false;
	/**
	 * Fixed emit offset from the vertex in model space (rotates with the
	 * player's facing), local units. X is sideways, Y is forward/back,
	 * Z is up (positive).
	 */
	private int offsetX = 0;
	private int offsetY = 0;
	private int offsetZ = 0;

	EmitterProfile()
	{
	}

	EmitterProfile(String name)
	{
		this.name = name;
	}

	EmitterProfile copy()
	{
		EmitterProfile c = new EmitterProfile(name);
		c.targetType = targetType;
		c.projectileId = projectileId;
		c.objectId = objectId;
		c.npcId = npcId;
		c.graphicId = graphicId;
		c.signature = signature;
		c.enabled = enabled;
		c.wip = wip;
		c.folderId = folderId;
		c.vertices = new HashSet<>(vertices);
		c.copyStyleFrom(this);
		return c;
	}

	boolean isProjectileTarget()
	{
		return TARGET_PROJECTILE.equals(targetType);
	}

	boolean isObjectTarget()
	{
		return TARGET_OBJECT.equals(targetType);
	}

	boolean isNpcTarget()
	{
		return TARGET_NPC.equals(targetType);
	}

	boolean isGraphicTarget()
	{
		return TARGET_GRAPHIC.equals(targetType);
	}

	/**
	 * Copy the editable settings: style plus the item variant filter.
	 */
	void copyStyleFrom(EmitterProfile other)
	{
		color = other.color;
		colorFade = other.colorFade;
		colorEnd = other.colorEnd;
		colorFadeStart = other.colorFadeStart;
		shape = other.shape;
		size = other.size;
		sizeJitter = other.sizeJitter;
		particlesPerSecond = other.particlesPerSecond;
		trailDensity = other.trailDensity;
		lifetimeMs = other.lifetimeMs;
		riseSpeed = other.riseSpeed;
		spreadSpeed = other.spreadSpeed;
		gravity = other.gravity;
		windX = other.windX;
		windY = other.windY;
		windZ = other.windZ;
		drag = other.drag;
		vortex = other.vortex;
		emitScale = other.emitScale;
		stretch = other.stretch;
		stretchRamp = other.stretchRamp;
		spawnJitter = other.spawnJitter;
		featherStrength = other.featherStrength;
		interpolation = other.interpolation;
		depthBias = other.depthBias;
		movementLifetime = other.movementLifetime;
		offsetX = other.offsetX;
		offsetY = other.offsetY;
		offsetZ = other.offsetZ;
		itemIds = new HashSet<>(other.itemIds);
		animationIds = new HashSet<>(other.animationIds);
		animFrames = other.animFrames;
	}
}

package dev.cnnnr;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.HashSet;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.IntConsumer;
import javax.swing.JPanel;

/**
 * Software-rendered wireframe viewer for a {@link ModelSnapshot}.
 * Drag to orbit, scroll to zoom, hover to inspect a vertex, click to toggle
 * a vertex as an emitter. Shift+drag box-adds many vertices at once;
 * Ctrl+drag box-removes them.
 */
class ViewportPanel extends JPanel
{
	private static final Color COLOR_BACKGROUND = new Color(27, 27, 31);
	private static final Color COLOR_EDGE = new Color(62, 62, 72);
	private static final Color COLOR_VERTEX = new Color(170, 170, 180);
	private static final Color COLOR_HOVER = new Color(0, 220, 255);
	private static final Color COLOR_SELECTED = new Color(255, 152, 31);
	private static final Color COLOR_TEXT = new Color(200, 200, 205);
	private static final int HIT_RADIUS = 10;

	private final IntConsumer onVertexToggled;

	/**
	 * Box selection result: the vertices inside the box, and true to add them
	 * as emitters or false to remove them.
	 */
	private final BiConsumer<Set<Integer>, Boolean> onBoxSelected;

	private ModelSnapshot snapshot;
	private int pieceFilter = -1; // -1 = all pieces

	/**
	 * Scrubber pose: replacement vertex positions sharing the snapshot's
	 * topology, or null to show the snapshot's own pose.
	 */
	private float[] overrideX;
	private float[] overrideY;
	private float[] overrideZ;

	private double yaw = 0.5;
	private double pitch = 0.25;
	private double zoom = 1.0;

	// Fit computed from the visible vertex set
	private float centerX, centerY, centerZ;
	private float fitRadius = 1;

	// Per-vertex projection cache, rebuilt each paint, used for hit testing
	private int[] screenX;
	private int[] screenY;
	private boolean[] vertexVisible;

	private int hoverVertex = -1;
	private Set<Integer> selectedVertices = new HashSet<>();
	private boolean labelAll;

	private int lastDragX, lastDragY;
	private boolean dragged;

	// Rubber-band box selection state (shift+drag adds, ctrl+drag removes)
	private boolean boxSelecting;
	private boolean boxRemove;
	private int boxStartX, boxStartY, boxEndX, boxEndY;

	ViewportPanel(IntConsumer onVertexToggled, BiConsumer<Set<Integer>, Boolean> onBoxSelected)
	{
		this.onVertexToggled = onVertexToggled;
		this.onBoxSelected = onBoxSelected;
		setBackground(COLOR_BACKGROUND);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				lastDragX = e.getX();
				lastDragY = e.getY();
				dragged = false;
				boxSelecting = e.isShiftDown() || e.isControlDown();
				boxRemove = e.isControlDown();
				boxStartX = boxEndX = e.getX();
				boxStartY = boxEndY = e.getY();
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				int dx = e.getX() - lastDragX;
				int dy = e.getY() - lastDragY;
				if (Math.abs(dx) + Math.abs(dy) > 2)
				{
					dragged = true;
				}
				if (boxSelecting)
				{
					boxEndX = e.getX();
					boxEndY = e.getY();
				}
				else
				{
					yaw += dx * 0.012;
					pitch = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, pitch + dy * 0.012));
				}
				lastDragX = e.getX();
				lastDragY = e.getY();
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (boxSelecting)
				{
					finishBoxSelection();
					return;
				}
				if (!dragged && hoverVertex != -1)
				{
					onVertexToggled.accept(hoverVertex);
				}
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				int previous = hoverVertex;
				hoverVertex = findVertexAt(e.getX(), e.getY());
				if (hoverVertex != previous)
				{
					repaint();
				}
			}

			@Override
			public void mouseWheelMoved(MouseWheelEvent e)
			{
				zoom = Math.max(0.2, Math.min(25.0, zoom * Math.pow(1.12, -e.getWheelRotation())));
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
		addMouseWheelListener(mouse);
	}

	void setSnapshot(ModelSnapshot snapshot)
	{
		this.snapshot = snapshot;
		this.pieceFilter = -1;
		this.hoverVertex = -1;
		this.overrideX = null;
		this.overrideY = null;
		this.overrideZ = null;
		screenX = new int[snapshot.getVertexCount()];
		screenY = new int[snapshot.getVertexCount()];
		vertexVisible = new boolean[snapshot.getVertexCount()];
		fit();
		repaint();
	}

	void setPieceFilter(int pieceIndex)
	{
		this.pieceFilter = pieceIndex;
		this.hoverVertex = -1;
		fit();
		repaint();
	}

	void setSelectedVertices(Set<Integer> vertices)
	{
		this.selectedVertices = new HashSet<>(vertices);
		repaint();
	}

	void setLabelAll(boolean labelAll)
	{
		this.labelAll = labelAll;
		repaint();
	}

	/**
	 * Show a different pose of the same topology (the animation scrubber);
	 * null restores the snapshot's own pose. Length-mismatched arrays are
	 * ignored rather than risking out-of-bounds projection.
	 */
	void setPositionOverride(float[] xs, float[] ys, float[] zs)
	{
		// Live model arrays are backing buffers that may run longer than the
		// vertex count; only reject arrays too SHORT to project safely
		if (snapshot != null && xs != null && xs.length < snapshot.getVertexCount())
		{
			return;
		}
		overrideX = xs;
		overrideY = ys;
		overrideZ = zs;
		repaint();
	}

	/**
	 * Recompute the view center and fit radius from the visible vertices.
	 */
	private void fit()
	{
		if (snapshot == null)
		{
			return;
		}

		updateVisibility();

		float sx = 0, sy = 0, sz = 0;
		int n = 0;
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			if (!vertexVisible[v])
			{
				continue;
			}
			sx += snapshot.getVerticesX()[v];
			sy += snapshot.getVerticesY()[v];
			sz += snapshot.getVerticesZ()[v];
			n++;
		}
		if (n == 0)
		{
			return;
		}
		centerX = sx / n;
		centerY = sy / n;
		centerZ = sz / n;

		float maxDistSq = 1;
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			if (!vertexVisible[v])
			{
				continue;
			}
			float dx = snapshot.getVerticesX()[v] - centerX;
			float dy = snapshot.getVerticesY()[v] - centerY;
			float dz = snapshot.getVerticesZ()[v] - centerZ;
			float distSq = dx * dx + dy * dy + dz * dz;
			if (distSq > maxDistSq)
			{
				maxDistSq = distSq;
			}
		}
		fitRadius = (float) Math.sqrt(maxDistSq);
		zoom = 1.0;
	}

	private void updateVisibility()
	{
		if (pieceFilter < 0 || pieceFilter >= snapshot.getPieces().size())
		{
			for (int v = 0; v < vertexVisible.length; v++)
			{
				vertexVisible[v] = true;
			}
			return;
		}

		for (int v = 0; v < vertexVisible.length; v++)
		{
			vertexVisible[v] = false;
		}
		for (int v : snapshot.getPieces().get(pieceFilter).getVertices())
		{
			vertexVisible[v] = true;
		}
	}

	private void finishBoxSelection()
	{
		boxSelecting = false;
		int x0 = Math.min(boxStartX, boxEndX);
		int x1 = Math.max(boxStartX, boxEndX);
		int y0 = Math.min(boxStartY, boxEndY);
		int y1 = Math.max(boxStartY, boxEndY);
		repaint();

		if (snapshot == null || (x1 - x0 < 4 && y1 - y0 < 4))
		{
			return;
		}

		Set<Integer> inside = new HashSet<>();
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			if (vertexVisible[v]
				&& screenX[v] >= x0 && screenX[v] <= x1
				&& screenY[v] >= y0 && screenY[v] <= y1)
			{
				inside.add(v);
			}
		}
		if (!inside.isEmpty())
		{
			onBoxSelected.accept(inside, !boxRemove);
		}
	}

	private int findVertexAt(int x, int y)
	{
		if (snapshot == null)
		{
			return -1;
		}
		int best = -1;
		int bestDistSq = HIT_RADIUS * HIT_RADIUS;
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			if (!vertexVisible[v])
			{
				continue;
			}
			int dx = screenX[v] - x;
			int dy = screenY[v] - y;
			int distSq = dx * dx + dy * dy;
			if (distSq < bestDistSq)
			{
				bestDistSq = distSq;
				best = v;
			}
		}
		return best;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2 = (Graphics2D) g;

		if (snapshot == null)
		{
			g2.setColor(COLOR_TEXT);
			g2.drawString("No model snapshot. Log in and press Refresh.", 20, 30);
			return;
		}

		project();

		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setStroke(new BasicStroke(1f));

		// Edges
		g2.setColor(COLOR_EDGE);
		int[] f1 = snapshot.getFaceIndices1();
		int[] f2 = snapshot.getFaceIndices2();
		int[] f3 = snapshot.getFaceIndices3();
		for (int f = 0; f < snapshot.getFaceCount(); f++)
		{
			int a = f1[f], b = f2[f], c = f3[f];
			if (!vertexVisible[a])
			{
				continue;
			}
			g2.drawLine(screenX[a], screenY[a], screenX[b], screenY[b]);
			g2.drawLine(screenX[b], screenY[b], screenX[c], screenY[c]);
			g2.drawLine(screenX[c], screenY[c], screenX[a], screenY[a]);
		}

		// Vertices
		g2.setColor(COLOR_VERTEX);
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			if (vertexVisible[v])
			{
				g2.fillRect(screenX[v] - 1, screenY[v] - 1, 3, 3);
			}
		}

		for (int v : selectedVertices)
		{
			if (v >= 0 && v < snapshot.getVertexCount() && vertexVisible[v])
			{
				drawMarkedVertex(g2, v, COLOR_SELECTED, labelAll);
			}
		}
		if (hoverVertex != -1 && !selectedVertices.contains(hoverVertex))
		{
			drawMarkedVertex(g2, hoverVertex, COLOR_HOVER, true);
		}

		// Rubber-band box
		if (boxSelecting)
		{
			int x0 = Math.min(boxStartX, boxEndX);
			int y0 = Math.min(boxStartY, boxEndY);
			int w = Math.abs(boxEndX - boxStartX);
			int h = Math.abs(boxEndY - boxStartY);
			Color boxColor = boxRemove ? COLOR_SELECTED : COLOR_HOVER;
			g2.setColor(new Color(boxColor.getRed(), boxColor.getGreen(), boxColor.getBlue(), 40));
			g2.fillRect(x0, y0, w, h);
			g2.setColor(boxColor);
			g2.drawRect(x0, y0, w, h);
		}

		// Status line
		g2.setColor(COLOR_TEXT);
		g2.setFont(g2.getFont().deriveFont(Font.PLAIN, 12f));
		String status = snapshot.getVertexCount() + " vertices, " + snapshot.getFaceCount() + " faces"
			+ (pieceFilter >= 0 ? "  |  piece " + (pieceFilter + 1) : "")
			+ "  |  emitters: " + selectedVertices.size()
			+ "  |  drag orbits, click toggles, shift+drag box-adds, ctrl+drag box-removes";
		g2.drawString(status, 10, getHeight() - 10);
	}

	private void drawMarkedVertex(Graphics2D g2, int v, Color color, boolean label)
	{
		g2.setColor(color);
		g2.fillOval(screenX[v] - 3, screenY[v] - 3, 7, 7);
		g2.drawOval(screenX[v] - 6, screenY[v] - 6, 13, 13);
		if (label)
		{
			g2.drawString("v" + v, screenX[v] + 9, screenY[v] - 6);
		}
	}

	private void project()
	{
		double cosYaw = Math.cos(yaw), sinYaw = Math.sin(yaw);
		double cosPitch = Math.cos(pitch), sinPitch = Math.sin(pitch);
		double scale = Math.min(getWidth(), getHeight()) * 0.45 / fitRadius * zoom;
		int halfW = getWidth() / 2;
		int halfH = getHeight() / 2;

		float[] vx = overrideX != null ? overrideX : snapshot.getVerticesX();
		float[] vy = overrideY != null ? overrideY : snapshot.getVerticesY();
		float[] vz = overrideZ != null ? overrideZ : snapshot.getVerticesZ();
		for (int v = 0; v < snapshot.getVertexCount(); v++)
		{
			double dx = vx[v] - centerX;
			double dy = vy[v] - centerY;
			double dz = vz[v] - centerZ;

			double rx = dx * cosYaw + dz * sinYaw;
			double rz = -dx * sinYaw + dz * cosYaw;
			double ry = dy * cosPitch - rz * sinPitch;

			screenX[v] = halfW + (int) (rx * scale);
			screenY[v] = halfH + (int) (ry * scale);
		}
	}
}

package dev.cnnnr;

/**
 * Particle silhouette. Default is the soft round glow; Diamond warps the
 * shared billboard disc's vertices into a four-point diamond. Warping keeps
 * the mesh topology intact, so the batch canvas is unaffected.
 */
enum Shape
{
	DEFAULT("Default"),
	DIAMOND("Diamond");

	private final String label;

	Shape(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package dev.cnnnr;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.ItemID;

/**
 * Renders particles as camera-facing soft discs, batched into one merged
 * scene model per occupied tile.
 *
 * The client draws renderables through per-tile slots, and a tile only holds
 * a few - hundreds of individual RuneLiteObjects stacked on the same tile
 * mostly don't draw. So, like the game's own area effects, all particles on a
 * tile are merged into a single model rendered by one pooled RuneLiteObject.
 *
 * To keep the hot path allocation-free, batches are pre-built "canvases":
 * a model merged and lit ONCE from K disc slots, whose live vertex,
 * transparency and color arrays are then overwritten in place every tick -
 * no clones, merges or relights at steady state. Vertices are billboarded
 * toward the camera during the write; transparency (fade x radial falloff)
 * and colors are array-copied from pre-baked per-style templates, only when
 * a slot's style, size or fade step changes. Both lit and unlit color arrays
 * are written since renderers differ in which they consume.
 *
 * The engine welds identical-position vertices when merging, which would
 * break slot slicing, so the canvas prototype gets tiny per-vertex epsilon
 * offsets and the build is verified; on failure the renderer falls back to
 * legacy per-tick merging.
 *
 * All methods must be called on the client thread.
 */
@Slf4j
class ParticleRenderer
{
	/**
	 * Thickness of the billboard lens relative to its radius. Nonzero so the
	 * two hemispheres of the flattened source mesh aren't perfectly coplanar.
	 */
	private static final float LENS_FLATTEN = 0.12f;
	/**
	 * High ambient and weak directional light so discs read as self-lit glow
	 * instead of shaded surfaces.
	 */
	private static final int LIGHT_AMBIENT = 90;
	private static final int LIGHT_CONTRAST = 2000;
	/**
	 * Caps per batch model, from the GPU plugin's FacePrioritySorter budgets
	 * (6500 vertices, 4000 faces per priority - our faces share one priority).
	 * A tile gets multiple batch objects if its particles exceed a canvas.
	 */
	private static final int MAX_FACES_PER_BATCH = 3500;
	private static final int MAX_VERTICES_PER_BATCH = 6000;
	private static final byte INVISIBLE = (byte) 254;

	/**
	 * Fixed volume around the tile center that canvas geometry must stay
	 * inside. Model bounds are computed ONCE over this volume at build time
	 * (the engine caches bounds; recomputing on mutated models is a no-op),
	 * so runtime writes are clamped into it - otherwise the GPU plugin's
	 * depth sort asserts on vertices outside the frozen radius.
	 */
	private static final float VOLUME_HORIZONTAL = 256f;
	private static final float VOLUME_UP = -1200f;
	private static final float VOLUME_DOWN = 200f;
	private static final float CLAMP_MARGIN = 56f;

	/**
	 * A pre-merged, pre-lit batch model whose arrays are rewritten in place.
	 */
	private class BatchCanvas
	{
		final ModelData modelData;
		final Model lit;
		final float[] vx, vy, vz;
		final byte[] transparencies;
		final short[] unlitColors;
		final int[] colors1, colors2, colors3;
		final RuneLiteObject object;
		final ParticleStyle[] slotStyle;
		final int[] slotVariant;

		boolean claimed;
		long tileKey;
		LocalPoint centerLp;
		int centerHeight;
		int usedSlots;
		/**
		 * Highest slot count written since slots were last cleared; slots in
		 * [usedSlots, highWater) hold stale geometry and need clearing.
		 */
		int highWater;

		BatchCanvas(ModelData merged)
		{
			modelData = merged;
			lit = merged.light(LIGHT_AMBIENT, LIGHT_CONTRAST,
				ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
			vx = merged.getVerticesX();
			vy = merged.getVerticesY();
			vz = merged.getVerticesZ();
			transparencies = merged.getFaceTransparencies();
			unlitColors = merged.getFaceColors();
			colors1 = lit.getFaceColors1();
			colors2 = lit.getFaceColors2();
			colors3 = lit.getFaceColors3();
			slotStyle = new ParticleStyle[slotsPerCanvas];
			slotVariant = new int[slotsPerCanvas];
			Arrays.fill(slotVariant, -1);

			// Lock in bounds NOW, while the geometry spans the whole clamp
			// volume: the engine computes bounds once and caches, so this is
			// the only computation the model ever gets
			lit.calculateBoundsCylinder();
			for (int slot = 0; slot < slotsPerCanvas; slot++)
			{
				clearSlot(this, slot);
			}

			object = client.createRuneLiteObject();
			object.setDrawFrontTilesFirst(true);
			object.setOrientation(0);
			object.setModel(lit);
		}
	}

	private final Client client;

	private final List<BatchCanvas> canvases = new ArrayList<>();
	private boolean canvasModeFailed;
	private ModelData canvasProto;
	private int slotsPerCanvas;
	/**
	 * Per-tick scratch for O(1) canvas claims: tile -> the canvas currently
	 * filling for that tile, plus a cursor into the pool. Claims only ever
	 * advance the cursor, so canvases claimed this tick are exactly the pool
	 * prefix [0, idleCursor).
	 */
	private final Map<Long, BatchCanvas> tileCanvases = new HashMap<>();
	private int idleCursor;

	/**
	 * Legacy per-tick merge path, kept as fallback if canvas slicing fails.
	 */
	private final List<RuneLiteObject> legacyPool = new ArrayList<>();
	private int legacyUsed;

	/**
	 * Resolved styles by profile key, rebuilt when profiles change.
	 */
	private final Map<String, ParticleStyle> styles = new HashMap<>();
	private ModelData sourceMesh;
	private int templateVertexCount;
	private int templateFaceCount;

	/**
	 * Diagnostics.
	 */
	@Getter
	private int activeObjects;
	@Getter
	private int lastBatchedVertices;
	private int outOfSceneKills;

	ParticleRenderer(Client client)
	{
		this.client = client;
	}

	boolean isReady()
	{
		return sourceMesh != null && !styles.isEmpty();
	}

	/**
	 * @return the resolved style for a profile key, or null
	 */
	ParticleStyle getStyle(String profileKey)
	{
		return styles.get(profileKey);
	}

	/**
	 * (Re)build disc templates for every profile's style.
	 *
	 * @return true on success
	 */
	boolean rebuildStyles(Map<String, EmitterProfile> profiles)
	{
		if (sourceMesh == null)
		{
			sourceMesh = loadSourceMesh();
			if (sourceMesh == null)
			{
				log.debug("Particle base model not yet available");
				return false;
			}
			templateVertexCount = sourceMesh.getVerticesCount();
			templateFaceCount = sourceMesh.getFaceCount();
			slotsPerCanvas = Math.max(1, Math.min(
				MAX_FACES_PER_BATCH / Math.max(1, templateFaceCount),
				MAX_VERTICES_PER_BATCH / Math.max(1, templateVertexCount)));
			if (slotsPerCanvas < 8)
			{
				// Canvas bounds need the eight corner slots; a mesh this heavy
				// can't batch safely, so take the per-tick merge path instead
				log.warn("Particle mesh too heavy for canvas batching ({}v {}f); using per-tick merging",
					templateVertexCount, templateFaceCount);
				canvasModeFailed = true;
			}
			buildCanvasProto();
		}

		styles.clear();
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			styles.put(entry.getKey(), buildStyle(entry.getValue()));
		}
		return true;
	}

	/**
	 * The canvas prototype is the disc topology with every vertex nudged by a
	 * unique epsilon, so the engine's identical-position vertex welding can't
	 * fuse slots (or vertices within a slot) when canvases are merged.
	 * Positions are overwritten every tick, so the nudges never render.
	 */
	private void buildCanvasProto()
	{
		canvasProto = sourceMesh.shallowCopy().cloneVertices();
		float[] xs = canvasProto.getVerticesX();
		float[] ys = canvasProto.getVerticesY();
		float[] zs = canvasProto.getVerticesZ();
		for (int j = 0; j < templateVertexCount; j++)
		{
			xs[j] += j * 0.001953125f;
			ys[j] += j * 0.0009765625f;
			zs[j] += j * 0.00048828125f;
		}
	}

	private ParticleStyle buildStyle(EmitterProfile profile)
	{
		int startArgb = profile.getColor();
		int endArgb = profile.getColorEnd();
		// Colour over life: interpolate start -> end across the fade steps. Only
		// when the author opts in and the colours differ; otherwise the original
		// constant-colour bake stands.
		boolean gradient = profile.isColorFade() && endArgb != startArgb;
		// Hold the start colour until this life fraction, then ramp to the end
		// by death, so the shift can be delayed to late in a particle's life.
		float fadeStart = Math.max(0, Math.min(100, profile.getColorFadeStart())) / 100f;
		float fadeSpan = Math.max(0.001f, 1f - fadeStart);

		ModelData[][] templates = new ModelData[ParticleStyle.SIZE_MULTIPLIERS.length][ParticleStyle.FADE_STEPS];
		for (int s = 0; s < ParticleStyle.SIZE_MULTIPLIERS.length; s++)
		{
			float radius = profile.getSize() / 2f * ParticleStyle.SIZE_MULTIPLIERS[s];
			ModelData lens = sourceMesh.shallowCopy()
				.cloneVertices()
				.cloneColors();
			spherify(lens, radius);
			flatten(lens, LENS_FLATTEN);

			// Warp the disc geometry into the profile's silhouette (star,
			// teardrop, cross) so the shape is real geometry, not a mask on a
			// round blob; topology is unchanged so the batch system holds
			Shape shape = profile.getShape() == null ? Shape.DEFAULT : profile.getShape();
			shapeWarp(lens, radius, shape);

			// Distinct source face colors to recolor, and the geometry falloff -
			// both independent of the per-fade colour, so computed once here
			Set<Short> originals = new HashSet<>();
			for (short faceColor : lens.getFaceColors())
			{
				originals.add(faceColor);
			}
			float[] radial = shapeFalloff(lens, radius, shape);

			for (int i = 0; i < ParticleStyle.FADE_STEPS; i++)
			{
				float life = (i + 0.5f) / ParticleStyle.FADE_STEPS;
				float fade = Math.max(0f, Math.min(1f, (life - fadeStart) / fadeSpan));
				int argb = gradient ? lerpArgb(startArgb, endArgb, fade) : startArgb;
				short target = JagexColor.rgbToHSL(argb, 1.0d);
				int fadeAlpha = (argb >>> 24) & 0xFF;
				// Soft life envelope: born invisible, bloom mid-life, melt away
				float envelope = envelope(life);
				ModelData variant = lens.shallowCopy().cloneColors().cloneTransparencies(true);
				for (short original : originals)
				{
					variant.recolor(original, target);
				}
				byte[] transparencies = variant.getFaceTransparencies();
				for (int f = 0; f < transparencies.length; f++)
				{
					int alpha = (int) (fadeAlpha * envelope * radial[f]);
					transparencies[f] = (byte) Math.min(254, Math.max(1, 255 - alpha));
				}
				templates[s][i] = variant;
			}
		}

		// Bake the lit colors per fade step; canvas slots copy them in place of
		// per-tick relighting. Without a gradient every step is identical and
		// the batch copies just once per style (see writeSlot).
		int[][] lit1 = new int[ParticleStyle.FADE_STEPS][];
		int[][] lit2 = new int[ParticleStyle.FADE_STEPS][];
		int[][] lit3 = new int[ParticleStyle.FADE_STEPS][];
		for (int i = 0; i < ParticleStyle.FADE_STEPS; i++)
		{
			Model probe = templates[1][i].shallowCopy().light(LIGHT_AMBIENT, LIGHT_CONTRAST,
				ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
			lit1[i] = probe.getFaceColors1().clone();
			lit2[i] = probe.getFaceColors2().clone();
			lit3[i] = probe.getFaceColors3().clone();
		}

		return new ParticleStyle(templates, lit1, lit2, lit3, profile);
	}

	/**
	 * Linear per-channel interpolation between two ARGB colours.
	 */
	private static int lerpArgb(int a, int b, float t)
	{
		int aa = (a >>> 24) & 0xFF, ar = (a >>> 16) & 0xFF, ag = (a >>> 8) & 0xFF, ab = a & 0xFF;
		int ba = (b >>> 24) & 0xFF, br = (b >>> 16) & 0xFF, bg = (b >>> 8) & 0xFF, bb = b & 0xFF;
		int oa = Math.round(aa + (ba - aa) * t);
		int or = Math.round(ar + (br - ar) * t);
		int og = Math.round(ag + (bg - ag) * t);
		int ob = Math.round(ab + (bb - ab) * t);
		return (oa << 24) | (or << 16) | (og << 8) | ob;
	}

	/**
	 * The disc topology every particle is molded from. Spherify normalizes
	 * the shape and size, so the pick trades vertex count (written per
	 * particle per tick) against how round the sphere projection comes out;
	 * the orb reads best. Slot capacity adapts to whatever this returns.
	 */
	private ModelData loadSourceMesh()
	{
		ItemComposition comp = client.getItemDefinition(ItemID.DS2_ORB_INERT);
		return client.loadModelData(comp.getInventoryModel());
	}

	/**
	 * Alpha over normalized age: smooth rise to a mid-life peak and gentle
	 * decay, instead of popping in at full brightness.
	 */
	private static float envelope(float ageFraction)
	{
		return (float) Math.pow(Math.sin(Math.PI * ageFraction), 0.8);
	}

	/**
	 * Push all live particles into batch models. Call once per client tick,
	 * after simulation.
	 */
	void sync(List<Particle> particles, int worldView, int level)
	{
		activeObjects = 0;
		lastBatchedVertices = 0;
		WorldView wv = client.getWorldView(worldView);
		if (wv == null || !isReady())
		{
			reset();
			return;
		}

		// Billboard basis: face every disc toward the camera, exactly. On the
		// GPU the scene is rendered with the floating point camera, which can
		// deviate from the int JAU camera - use whichever the renderer uses,
		// mirroring Perspective.localToCanvas
		float yaw;
		float pitch;
		if (client.isGpu())
		{
			yaw = client.getCameraFpYaw();
			pitch = client.getCameraFpPitch();
		}
		else
		{
			yaw = client.getCameraYaw() * (float) (Math.PI / 1024);
			pitch = client.getCameraPitch() * (float) (Math.PI / 1024);
		}
		float sinYaw = (float) Math.sin(yaw);
		float cosYaw = (float) Math.cos(yaw);
		float sinPitch = (float) Math.sin(pitch);
		float cosPitch = (float) Math.cos(pitch);

		if (canvasModeFailed)
		{
			syncLegacy(particles, wv, worldView, level, sinYaw, cosYaw, sinPitch, cosPitch);
			return;
		}
		syncCanvases(particles, wv, worldView, level, sinYaw, cosYaw, sinPitch, cosPitch);
	}

	private void syncCanvases(List<Particle> particles, WorldView wv, int worldView, int level,
		float sinYaw, float cosYaw, float sinPitch, float cosPitch)
	{
		for (BatchCanvas canvas : canvases)
		{
			canvas.claimed = false;
		}
		tileCanvases.clear();
		idleCursor = 0;
		// Consecutive particles usually share a tile; the memo skips the map
		long lastKey = Long.MIN_VALUE;
		BatchCanvas lastCanvas = null;

		for (Particle p : particles)
		{
			int x = (int) p.getX();
			int y = (int) p.getY();
			int sceneX = x >> 7;
			int sceneY = y >> 7;
			if (sceneX < 0 || sceneX >= wv.getSizeX() || sceneY < 0 || sceneY >= wv.getSizeY())
			{
				outOfSceneKills++;
				p.kill();
				continue;
			}
			long tileKey = ((long) sceneX << 32) | (sceneY & 0xffffffffL);

			BatchCanvas canvas;
			if (tileKey == lastKey && lastCanvas.usedSlots < slotsPerCanvas)
			{
				canvas = lastCanvas;
			}
			else
			{
				canvas = claimCanvas(tileKey, worldView, level);
				if (canvas == null)
				{
					// Canvas build failed; legacy path takes over next tick
					return;
				}
				lastKey = tileKey;
				lastCanvas = canvas;
			}
			writeSlot(canvas, canvas.usedSlots++, p, sinYaw, cosYaw, sinPitch, cosPitch);
			lastBatchedVertices += templateVertexCount;
		}

		for (BatchCanvas canvas : canvases)
		{
			if (!canvas.claimed)
			{
				if (canvas.object.isActive())
				{
					canvas.object.setActive(false);
				}
				continue;
			}

			// Collapse slots that were written last tick but not this one
			for (int slot = canvas.usedSlots; slot < canvas.highWater; slot++)
			{
				clearSlot(canvas, slot);
			}
			canvas.highWater = canvas.usedSlots;

			canvas.object.setLocation(canvas.centerLp, level);
			if (!canvas.object.isActive())
			{
				canvas.object.setActive(true);
			}
			activeObjects++;
		}
	}

	/**
	 * Find this tick's canvas for a tile (one with free slots), claiming an
	 * idle canvas or building a new one as needed. O(1): a map resolves the
	 * tile's current canvas and the cursor hands out idle ones in pool order.
	 * Canvas count grows to the peak concurrent demand and is reused
	 * thereafter.
	 */
	private BatchCanvas claimCanvas(long tileKey, int worldView, int level)
	{
		BatchCanvas current = tileCanvases.get(tileKey);
		if (current != null && current.usedSlots < slotsPerCanvas)
		{
			return current;
		}
		BatchCanvas idle;
		if (idleCursor < canvases.size())
		{
			idle = canvases.get(idleCursor++);
		}
		else
		{
			idle = buildCanvas();
			if (idle == null)
			{
				return null;
			}
			canvases.add(idle);
			idleCursor = canvases.size();
		}

		idle.claimed = true;
		idle.tileKey = tileKey;
		idle.usedSlots = 0;
		tileCanvases.put(tileKey, idle);
		int centerX = ((int) (tileKey >> 32) << 7) + 64;
		int centerY = (((int) tileKey) << 7) + 64;
		idle.centerLp = new LocalPoint(centerX, centerY, worldView);
		idle.centerHeight = Perspective.getTileHeight(client, idle.centerLp, level);
		return idle;
	}

	private BatchCanvas buildCanvas()
	{
		ModelData[] parts = new ModelData[slotsPerCanvas];
		for (int i = 0; i < slotsPerCanvas; i++)
		{
			// Distinct whole-unit offsets so welding can't fuse slots (the
			// epsilons are sub-unit). The first eight slots pin the corners of
			// the clamp volume, so the bounds computed ONCE over this geometry
			// cover everything runtime writes are clamped to no matter how few
			// slots the mesh's budget allows - the old interior-only spread
			// silently needed 216+ slots for full coverage and asserted the
			// GPU depth sort when a heavier mesh shrank the slot count. The
			// rest spread through the interior, shifted off the corner lattice
			// so no offset ever repeats.
			int x;
			int y;
			int z;
			if (i < 8)
			{
				x = (i & 1) == 0 ? -(int) VOLUME_HORIZONTAL : (int) VOLUME_HORIZONTAL;
				y = (i & 2) == 0 ? (int) VOLUME_UP : (int) VOLUME_DOWN;
				z = (i & 4) == 0 ? -(int) VOLUME_HORIZONTAL : (int) VOLUME_HORIZONTAL;
			}
			else
			{
				int k = i + 1;
				x = -(int) VOLUME_HORIZONTAL + (k % 9) * 64;
				y = (int) VOLUME_DOWN - ((k / 9) % 24) * 60;
				z = -(int) VOLUME_HORIZONTAL + ((k / 216) % 9) * 64;
			}
			parts[i] = canvasProto.shallowCopy().cloneVertices().translate(x, y, z);
		}
		ModelData merged = client.mergeModels(parts).cloneTransparencies(true);

		if (merged.getVerticesCount() != slotsPerCanvas * templateVertexCount
			|| merged.getFaceCount() != slotsPerCanvas * templateFaceCount)
		{
			log.warn("Canvas slicing failed ({}v {}f, expected {}x{}v {}f); falling back to per-tick merging",
				merged.getVerticesCount(), merged.getFaceCount(),
				slotsPerCanvas, templateVertexCount, templateFaceCount);
			canvasModeFailed = true;
			return null;
		}
		return new BatchCanvas(merged);
	}

	/**
	 * Overwrite one slot of a canvas with a particle: billboarded vertices
	 * always; transparencies only when the slot's size or fade step changed;
	 * colors only when its style changed - colors are fade-independent, the
	 * life envelope rides entirely in transparency.
	 */
	private void writeSlot(BatchCanvas canvas, int slot, Particle p,
		float sinYaw, float cosYaw, float sinPitch, float cosPitch)
	{
		ParticleStyle style = p.getStyle();
		int size = p.getSizeVariant();
		int fade = fadeStep(p.lifeFraction());

		// Per-particle base-size jitter: a uniform scale on the disc that rides
		// on top of the pre-baked auto-variation. Capped so growth can't push
		// the scaled disc out of the bounds volume (the un-jittered variant
		// already fits); shrinking is always safe.
		float sizeScale = p.getSizeScale();
		float variantRadius = style.getBaseSize() * 0.5f * ParticleStyle.SIZE_MULTIPLIERS[size];
		if (sizeScale > 1f && variantRadius > 1f)
		{
			sizeScale = Math.min(sizeScale, Math.max(1f, (CLAMP_MARGIN - 1f) / variantRadius));
		}

		int vertexBase = slot * templateVertexCount;
		float dx = p.getX() - canvas.centerLp.getX();
		float dy = p.getZ() - canvas.centerHeight;
		float dz = p.getY() - canvas.centerLp.getY();

		// Nudge toward the camera so garment faces that beat their neighbors
		// by render priority (a cape over a skirt) don't swallow particles
		float bias = style.getDepthBias();
		if (bias > 0)
		{
			dx += bias * sinYaw * cosPitch;
			dy -= bias * sinPitch;
			dz -= bias * cosYaw * cosPitch;
		}

		// Clamp into the bounds volume the canvas was built over; vertices
		// outside the once-computed model radius break the GPU depth sort
		dx = clamp(dx, -VOLUME_HORIZONTAL + CLAMP_MARGIN, VOLUME_HORIZONTAL - CLAMP_MARGIN);
		dy = clamp(dy, VOLUME_UP + CLAMP_MARGIN, VOLUME_DOWN - CLAMP_MARGIN);
		dz = clamp(dz, -VOLUME_HORIZONTAL + CLAMP_MARGIN, VOLUME_HORIZONTAL - CLAMP_MARGIN);

		// Velocity-aligned stretch: elongate the disc along the particle's
		// screen-projected velocity (drips read as falling streaks). Capped
		// so the stretched radius stays within CLAMP_MARGIN and thus in the
		// bounds volume. du/dv is the velocity's direction in the billboard's
		// local (x,y) plane; the model frame is X=east, Y=height, Z=north.
		float stretch = style.getStretchFactor();
		float du = 0f;
		float dv = 0f;
		if (stretch > 1f)
		{
			float discRadius = variantRadius * sizeScale;
			if (discRadius > 1f)
			{
				stretch = Math.min(stretch, Math.max(1f, (CLAMP_MARGIN - 1f) / discRadius));
			}
			// Ramp toward the (already bounds-capped) peak over the particle's
			// life: a droplet holds its round shape while falling, then
			// elongates late as it "lets go". Late-biased so the stretch stays
			// subtle until the end. rampStart 1 = full stretch from spawn.
			float rampStart = style.getStretchRampStart();
			if (rampStart < 1f)
			{
				float ageFrac = 1f - p.lifeFraction();
				float r = rampStart + (1f - rampStart) * ageFrac * ageFrac;
				stretch = 1f + (stretch - 1f) * r;
			}
			if (stretch > 1f)
			{
				float vE = p.getVelX();
				float vH = p.getVelZ();
				float vN = p.getVelY();
				float u = vE * cosYaw + vN * sinYaw;
				float v = vE * sinPitch * sinYaw + vH * cosPitch - vN * sinPitch * cosYaw;
				float mag = (float) Math.sqrt(u * u + v * v);
				if (mag > 0.001f)
				{
					du = u / mag;
					dv = v / mag;
				}
			}
		}
		boolean stretched = stretch > 1f && (du != 0f || dv != 0f);

		ModelData sizeTemplate = style.getTemplates()[size][0];
		float[] sx = sizeTemplate.getVerticesX();
		float[] sy = sizeTemplate.getVerticesY();
		float[] sz = sizeTemplate.getVerticesZ();
		for (int j = 0; j < templateVertexCount; j++)
		{
			float x = sx[j] * sizeScale;
			float y = sy[j] * sizeScale;
			float z = sz[j] * sizeScale;

			if (stretched)
			{
				// Scale the component along the velocity direction, leaving
				// the perpendicular unchanged - an elongated streak
				float along = (stretch - 1f) * (x * du + y * dv);
				x += along * du;
				y += along * dv;
			}

			// Pitch: (0,0,1) -> (0, sinPitch, cosPitch)
			float y1 = y * cosPitch + z * sinPitch;
			float z1 = -y * sinPitch + z * cosPitch;

			// Yaw: (0, sp, cp) -> (-sinYaw*cp, sp, cosYaw*cp) = camera forward
			float x1 = -z1 * sinYaw + x * cosYaw;
			float z2 = z1 * cosYaw + x * sinYaw;

			canvas.vx[vertexBase + j] = x1 + dx;
			canvas.vy[vertexBase + j] = y1 + dy;
			canvas.vz[vertexBase + j] = z2 + dz;
		}

		int variant = size * ParticleStyle.FADE_STEPS + fade;
		int faceBase = slot * templateFaceCount;
		boolean gradient = style.isColorGradient();
		if (canvas.slotStyle[slot] != style)
		{
			canvas.slotStyle[slot] = style;
			canvas.slotVariant[slot] = -1;
			// Without a gradient the colour is constant over life, so copy it
			// once when the slot changes hands between styles. Unlit colors are
			// for renderers that relight, lit for the others.
			if (!gradient)
			{
				System.arraycopy(style.getTemplates()[size][0].getFaceColors(), 0,
					canvas.unlitColors, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors1()[0], 0, canvas.colors1, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors2()[0], 0, canvas.colors2, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors3()[0], 0, canvas.colors3, faceBase, templateFaceCount);
			}
		}
		if (canvas.slotVariant[slot] != variant)
		{
			canvas.slotVariant[slot] = variant;
			System.arraycopy(style.getTemplates()[size][fade].getFaceTransparencies(), 0,
				canvas.transparencies, faceBase, templateFaceCount);
			// With a gradient the colour moves each fade step, so recopy it here
			if (gradient)
			{
				System.arraycopy(style.getTemplates()[size][fade].getFaceColors(), 0,
					canvas.unlitColors, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors1()[fade], 0, canvas.colors1, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors2()[fade], 0, canvas.colors2, faceBase, templateFaceCount);
				System.arraycopy(style.getLitColors3()[fade], 0, canvas.colors3, faceBase, templateFaceCount);
			}
		}
	}

	private static float clamp(float v, float min, float max)
	{
		return v < min ? min : Math.min(v, max);
	}

	private void clearSlot(BatchCanvas canvas, int slot)
	{
		int vertexBase = slot * templateVertexCount;
		Arrays.fill(canvas.vx, vertexBase, vertexBase + templateVertexCount, 0f);
		Arrays.fill(canvas.vy, vertexBase, vertexBase + templateVertexCount, 0f);
		Arrays.fill(canvas.vz, vertexBase, vertexBase + templateVertexCount, 0f);
		int faceBase = slot * templateFaceCount;
		Arrays.fill(canvas.transparencies, faceBase, faceBase + templateFaceCount, INVISIBLE);
		canvas.slotStyle[slot] = null;
		canvas.slotVariant[slot] = -1;
	}

	/**
	 * Legacy fallback: merge and light fresh batch models every tick.
	 */
	private void syncLegacy(List<Particle> particles, WorldView wv, int worldView, int level,
		float sinYaw, float cosYaw, float sinPitch, float cosPitch)
	{
		legacyUsed = 0;

		Map<Long, List<Particle>> byTile = new HashMap<>();
		for (Particle p : particles)
		{
			int x = (int) p.getX();
			int y = (int) p.getY();
			int sceneX = x >> 7;
			int sceneY = y >> 7;
			if (sceneX < 0 || sceneX >= wv.getSizeX() || sceneY < 0 || sceneY >= wv.getSizeY())
			{
				outOfSceneKills++;
				p.kill();
				continue;
			}
			long key = ((long) sceneX << 32) | (sceneY & 0xffffffffL);
			byTile.computeIfAbsent(key, k -> new ArrayList<>()).add(p);
		}

		int batchSize = Math.max(1, MAX_FACES_PER_BATCH / Math.max(1, templateFaceCount));
		ModelData[] parts = new ModelData[batchSize];

		for (Map.Entry<Long, List<Particle>> entry : byTile.entrySet())
		{
			int sceneX = (int) (entry.getKey() >> 32);
			int sceneY = entry.getKey().intValue();
			int centerX = (sceneX << 7) + 64;
			int centerY = (sceneY << 7) + 64;
			LocalPoint centerLp = new LocalPoint(centerX, centerY, worldView);
			int centerHeight = Perspective.getTileHeight(client, centerLp, level);

			List<Particle> group = entry.getValue();
			for (int start = 0; start < group.size(); start += batchSize)
			{
				int n = Math.min(batchSize, group.size() - start);
				for (int i = 0; i < n; i++)
				{
					Particle p = group.get(start + i);
					ModelData md = p.getStyle().getTemplates()
						[p.getSizeVariant()][fadeStep(p.lifeFraction())]
						.shallowCopy()
						.cloneVertices();
					float bias = p.getStyle().getDepthBias();
					transformLegacy(md, sinYaw, cosYaw, sinPitch, cosPitch,
						p.getX() - centerX + bias * sinYaw * cosPitch,
						p.getZ() - centerHeight - bias * sinPitch,
						p.getY() - centerY - bias * cosYaw * cosPitch);
					parts[i] = md;
					lastBatchedVertices += templateVertexCount;
				}

				ModelData merged = n == batchSize
					? client.mergeModels(parts)
					: client.mergeModels(Arrays.copyOf(parts, n));
				Model lit = merged.light(LIGHT_AMBIENT, LIGHT_CONTRAST,
					ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);

				RuneLiteObject obj = nextLegacyObject();
				obj.setModel(lit);
				obj.setLocation(centerLp, level);
				obj.setOrientation(0);
			}
		}

		for (int i = legacyUsed; i < legacyPool.size(); i++)
		{
			RuneLiteObject obj = legacyPool.get(i);
			if (obj.isActive())
			{
				obj.setActive(false);
			}
		}
		activeObjects = legacyUsed;
	}

	private static void transformLegacy(ModelData md, float sinYaw, float cosYaw, float sinPitch, float cosPitch,
		float dx, float dy, float dz)
	{
		float[] xs = md.getVerticesX();
		float[] ys = md.getVerticesY();
		float[] zs = md.getVerticesZ();
		for (int i = 0; i < md.getVerticesCount(); i++)
		{
			float x = xs[i];
			float y = ys[i];
			float z = zs[i];
			float y1 = y * cosPitch + z * sinPitch;
			float z1 = -y * sinPitch + z * cosPitch;
			float x1 = -z1 * sinYaw + x * cosYaw;
			float z2 = z1 * cosYaw + x * sinYaw;
			xs[i] = x1 + dx;
			ys[i] = y1 + dy;
			zs[i] = z2 + dz;
		}
	}

	private RuneLiteObject nextLegacyObject()
	{
		RuneLiteObject obj;
		if (legacyUsed < legacyPool.size())
		{
			obj = legacyPool.get(legacyUsed);
		}
		else
		{
			obj = client.createRuneLiteObject();
			obj.setDrawFrontTilesFirst(true);
			legacyPool.add(obj);
		}
		legacyUsed++;
		if (!obj.isActive())
		{
			obj.setActive(true);
		}
		return obj;
	}

	/**
	 * Deactivate all batch objects, e.g. on logout or shutdown.
	 */
	void reset()
	{
		tileCanvases.clear();
		for (BatchCanvas canvas : canvases)
		{
			canvas.claimed = false;
			if (canvas.object.isActive())
			{
				canvas.object.setActive(false);
			}
		}
		for (RuneLiteObject obj : legacyPool)
		{
			if (obj.isActive())
			{
				obj.setActive(false);
			}
		}
		activeObjects = 0;
	}

	/**
	 * @return particles killed for leaving the scene since the last call
	 */
	int drainOutOfSceneKills()
	{
		int kills = outOfSceneKills;
		outOfSceneKills = 0;
		return kills;
	}

	private static int fadeStep(float lifeFraction)
	{
		int step = (int) ((1f - lifeFraction) * ParticleStyle.FADE_STEPS);
		return Math.max(0, Math.min(ParticleStyle.FADE_STEPS - 1, step));
	}

	/**
	 * Reshape a mesh into a sphere by projecting every vertex onto a sphere of
	 * the given radius around the mesh centroid. Topology is unchanged, so any
	 * reasonably round source model becomes a clean ball. The result is centered
	 * on the model origin so particles sit exactly on their emit position.
	 */
	private static void spherify(ModelData model, float radius)
	{
		float[] xs = model.getVerticesX();
		float[] ys = model.getVerticesY();
		float[] zs = model.getVerticesZ();
		int count = model.getVerticesCount();
		if (count == 0)
		{
			return;
		}

		float cx = 0, cy = 0, cz = 0;
		for (int i = 0; i < count; i++)
		{
			cx += xs[i];
			cy += ys[i];
			cz += zs[i];
		}
		cx /= count;
		cy /= count;
		cz /= count;

		for (int i = 0; i < count; i++)
		{
			float dx = xs[i] - cx;
			float dy = ys[i] - cy;
			float dz = zs[i] - cz;
			float len = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
			if (len < 0.001f)
			{
				// Degenerate vertex at the centroid; push it to the pole
				xs[i] = 0;
				ys[i] = -radius;
				zs[i] = 0;
				continue;
			}
			xs[i] = dx / len * radius;
			ys[i] = dy / len * radius;
			zs[i] = dz / len * radius;
		}
	}

	/**
	 * Squash the sphere along z into a thin lens: a billboard "quad" with the
	 * source mesh's topology. The disc spans x (horizontal) and y (vertical),
	 * facing along z.
	 */
	private static void flatten(ModelData model, float factor)
	{
		float[] zs = model.getVerticesZ();
		for (int i = 0; i < model.getVerticesCount(); i++)
		{
			zs[i] *= factor;
		}
	}

	/**
	 * Per-face alpha multiplier realizing the profile's shape as a soft mask
	 * over the disc, evaluated at each face centroid in the disc plane (x
	 * horizontal, y vertical). Default is the (1 - t^2)^2 radial glow; the
	 * others carve a silhouette while staying soft. Baked once per style.
	 */
	private static float[] shapeFalloff(ModelData model, float radius, Shape shape)
	{
		float[] xs = model.getVerticesX();
		float[] ys = model.getVerticesY();
		int[] f1 = model.getFaceIndices1();
		int[] f2 = model.getFaceIndices2();
		int[] f3 = model.getFaceIndices3();

		float[] falloff = new float[model.getFaceCount()];
		for (int f = 0; f < falloff.length; f++)
		{
			float cx = (xs[f1[f]] + xs[f2[f]] + xs[f3[f]]) / 3f;
			float cy = (ys[f1[f]] + ys[f2[f]] + ys[f3[f]]) / 3f;
			float nx = cx / radius;
			float ny = cy / radius;
			float t = Math.min(1f, (float) Math.sqrt(nx * nx + ny * ny));
			falloff[f] = maskValue(shape, nx, ny, t);
		}
		return falloff;
	}

	private static float maskValue(Shape shape, float nx, float ny, float t)
	{
		if (shape == Shape.DIAMOND)
		{
			// Geometry carries the silhouette; keep the interior a soft glow
			// (bright core, dimmer points) that never fully vanishes so the
			// warped points stay visible
			return 0.35f + 0.65f * (1f - t * t);
		}
		float a = 1f - t * t;
		return a * a;
	}

	/**
	 * Reposition the flattened disc's vertices into a four-point diamond by
	 * scaling each vertex's radius by a function of its angle (peaks on the
	 * axes). Topology is unchanged so the batch canvas is unaffected; Default
	 * is left round. x is horizontal, y vertical.
	 */
	private static void shapeWarp(ModelData model, float radius, Shape shape)
	{
		if (shape != Shape.DIAMOND)
		{
			return;
		}
		float[] xs = model.getVerticesX();
		float[] ys = model.getVerticesY();
		int count = model.getVerticesCount();
		for (int i = 0; i < count; i++)
		{
			float x = xs[i];
			float y = ys[i];
			if (x * x + y * y < 0.000001f)
			{
				continue;
			}
			// Four peaks on the axes; square sharpens the points
			float p = 0.5f + 0.5f * (float) Math.cos(4.0 * Math.atan2(y, x));
			float f = 0.3f + 0.7f * p * p;
			xs[i] = x * f;
			ys[i] = y * f;
		}
	}
}

package dev.cnnnr;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persistent emitter profiles. Each profile targets a mesh piece by topology
 * signature (see {@link ModelSnapshot.Piece}) and stores piece-local vertex
 * indices, so emitters survive model recomposition. Several profiles may
 * target the same signature, each optionally gated on worn item IDs, so
 * recolored variants of one model can carry different particles.
 *
 * Thread-safe: mutated from the Swing EDT (viewer clicks, sidebar actions)
 * and read from the client thread.
 */
@Slf4j
class EmitterStore
{
	private static final String CONFIG_KEY = "pieceProfiles";
	private static final String FOLDERS_KEY = "pieceFolders";
	private static final Type MAP_TYPE = new TypeToken<Map<String, EmitterProfile>>()
	{
	}.getType();
	private static final Type FOLDERS_TYPE = new TypeToken<Map<String, ProfileFolder>>()
	{
	}.getType();

	/**
	 * A consistent (profiles, folders) pair - both the merged result and the
	 * atomic read snapshot the emission gates and sidebar resolve against, so a
	 * profile is never scored against a folder map from a different instant.
	 */
	static final class Snapshot
	{
		final Map<String, EmitterProfile> profiles;
		final Map<String, ProfileFolder> folders;

		Snapshot(Map<String, EmitterProfile> profiles, Map<String, ProfileFolder> folders)
		{
			this.profiles = profiles;
			this.folders = folders;
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;
	/**
	 * In developer mode the config is the source of truth so authoring edits
	 * persist across reloads; shipped users instead take all profile content
	 * from the bundled pack and contribute only their enable/disable toggles,
	 * so preset style updates and new fields reach them on every update.
	 */
	private final boolean developerMode;
	private final Map<String, EmitterProfile> profiles = new LinkedHashMap<>();
	private final Map<String, ProfileFolder> folders = new LinkedHashMap<>();
	private int revision;

	/**
	 * Notified after any mutation; invoked on the calling thread.
	 */
	@Setter
	private Runnable changeListener;

	EmitterStore(ConfigManager configManager, Gson gson, boolean developerMode)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.developerMode = developerMode;
	}

	synchronized void load()
	{
		profiles.clear();
		folders.clear();
		Snapshot merged = mergeAll(
			configManager.getConfiguration(ParticlesConfig.GROUP, CONFIG_KEY),
			configManager.getConfiguration(ParticlesConfig.GROUP, FOLDERS_KEY));
		profiles.putAll(merged.profiles);
		folders.putAll(merged.folders);
	}

	/**
	 * Combine a user's saved config with the bundled preset pack and run
	 * migrations. Package-private so the contract can be tested without a
	 * ConfigManager.
	 *
	 * Developer mode: the config is the source of truth (authoring edits
	 * persist); the bundle only seeds a fresh, empty config, and presets are
	 * updated by re-exporting the config to presets.json.
	 *
	 * Shipped users: the bundle is the source of truth for CONTENT - every
	 * profile is taken wholesale from presets.json, so style changes and new
	 * fields ship on update - and only the user's enable/disable toggle is
	 * carried over from their saved config (the one thing they can change).
	 * A profile the bundle no longer contains is kept from the saved config.
	 */
	Map<String, EmitterProfile> mergeWithBundle(@Nullable String savedJson)
	{
		return mergeAll(savedJson, null).profiles;
	}

	/**
	 * Merge profiles and folders together and reconcile them: nulls any
	 * folderId that no longer resolves and dissolves folders left with fewer
	 * than two members, so the returned pair always satisfies the folder
	 * invariant. Package-private for testing.
	 */
	Snapshot mergeAll(@Nullable String savedProfilesJson, @Nullable String savedFoldersJson)
	{
		Map<String, EmitterProfile> saved = parse(savedProfilesJson);
		Map<String, EmitterProfile> bundled = parse(loadBundledPresets());

		Map<String, EmitterProfile> result = new LinkedHashMap<>();
		if (developerMode)
		{
			if (saved != null && !saved.isEmpty())
			{
				result.putAll(saved);
			}
			else if (bundled != null)
			{
				result.putAll(bundled);
			}
		}
		else
		{
			if (bundled != null)
			{
				bundled.forEach((key, profile) ->
				{
					EmitterProfile prior = saved == null ? null : saved.get(key);
					// Content from the bundle; the user's toggle carries over only
					// for profiles the bundle keeps ungrouped - foldered children
					// are dev-controlled (users toggle the folder, not the child).
					if (prior != null && profile.getFolderId() == null)
					{
						profile.setEnabled(prior.isEnabled());
					}
					result.put(key, profile);
				});
			}
			if (saved != null)
			{
				// Anything the bundle dropped (or the user created) survives
				saved.forEach(result::putIfAbsent);
			}
		}

		result.forEach((key, profile) ->
		{
			// Migration: profiles saved before item variants used their
			// signature as the map key
			if (profile.getSignature() == null)
			{
				profile.setSignature(key);
			}
			// Migration: single frame window fields became a range list
			if ((profile.getAnimFrames() == null || profile.getAnimFrames().isEmpty())
				&& (profile.getAnimFrameStart() >= 0 || profile.getAnimFrameEnd() >= 0))
			{
				int start = Math.max(0, profile.getAnimFrameStart());
				int end = profile.getAnimFrameEnd() < 0 ? 999 : profile.getAnimFrameEnd();
				profile.setAnimFrames(start + "-" + end);
				profile.setAnimFrameStart(-1);
				profile.setAnimFrameEnd(-1);
			}
			else if (profile.getAnimFrames() == null)
			{
				profile.setAnimFrames("");
			}
			// Migration: feather flag became a strength
			if (profile.isFeather() && profile.getFeatherStrength() == 0)
			{
				profile.setFeatherStrength(2);
				profile.setFeather(false);
			}
			// Migration: profiles saved before projectile targets
			if (profile.getTargetType() == null)
			{
				profile.setTargetType(EmitterProfile.TARGET_PLAYER);
			}
			// Migration: dynamic lifetime flag became a movement percent
			if (profile.isDynamicLifetime())
			{
				if (profile.getMovementLifetime() == 100)
				{
					profile.setMovementLifetime(50);
				}
				profile.setDynamicLifetime(false);
			}
			// Migration: profiles saved before shapes have no shape
			if (profile.getShape() == null)
			{
				profile.setShape(Shape.DEFAULT);
			}
			// Migration: emit scale is a percent defaulting to 100; a missing
			// key deserializes to 0, which would collapse emitters to a point
			if (profile.getEmitScale() <= 0)
			{
				profile.setEmitScale(100);
			}
			// Migration: end colour defaults to the start colour (no gradient);
			// a missing key deserializes to 0, which would fade to transparent
			if (profile.getColorEnd() == 0)
			{
				profile.setColorEnd(profile.getColor());
			}
		});

		Map<String, ProfileFolder> folderResult = mergeFolders(savedFoldersJson);
		reconcileFolders(result, folderResult);
		return new Snapshot(result, folderResult);
	}

	/**
	 * Merge saved folders with the bundle on the same terms as profiles:
	 * dev mode's config wins; shipped users take folder content from the bundle
	 * and keep only their own enable toggle.
	 */
	private Map<String, ProfileFolder> mergeFolders(@Nullable String savedFoldersJson)
	{
		Map<String, ProfileFolder> saved = parseFolders(savedFoldersJson);
		Map<String, ProfileFolder> bundled = parseFolders(loadBundledFolders());

		Map<String, ProfileFolder> result = new LinkedHashMap<>();
		if (developerMode)
		{
			if (saved != null && !saved.isEmpty())
			{
				result.putAll(saved);
			}
			else if (bundled != null)
			{
				result.putAll(bundled);
			}
		}
		else
		{
			if (bundled != null)
			{
				bundled.forEach((id, folder) ->
				{
					ProfileFolder prior = saved == null ? null : saved.get(id);
					if (prior != null)
					{
						// Content (name, wip) from the bundle, toggle from the user
						folder.setEnabled(prior.isEnabled());
					}
					result.put(id, folder);
				});
			}
			if (saved != null)
			{
				saved.forEach(result::putIfAbsent);
			}
		}
		return result;
	}

	/**
	 * Enforce the folder invariant on a merged pair: null any folderId with no
	 * matching folder, then drop any folder left with fewer than two members
	 * (nulling those members). Runs in both modes; defensive in dev mode where
	 * the mutators already hold the invariant.
	 */
	private static void reconcileFolders(Map<String, EmitterProfile> profiles,
		Map<String, ProfileFolder> folders)
	{
		for (EmitterProfile profile : profiles.values())
		{
			if (profile.getFolderId() != null && !folders.containsKey(profile.getFolderId()))
			{
				profile.setFolderId(null);
			}
		}
		Map<String, Integer> counts = new HashMap<>();
		for (EmitterProfile profile : profiles.values())
		{
			if (profile.getFolderId() != null)
			{
				counts.merge(profile.getFolderId(), 1, Integer::sum);
			}
		}
		folders.keySet().removeIf(id -> counts.getOrDefault(id, 0) < 2);
		for (EmitterProfile profile : profiles.values())
		{
			if (profile.getFolderId() != null && !folders.containsKey(profile.getFolderId()))
			{
				profile.setFolderId(null);
			}
		}
	}

	/**
	 * Parse a profile-map JSON string, or null on empty/blank/malformed.
	 */
	@Nullable
	private Map<String, EmitterProfile> parse(@Nullable String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, MAP_TYPE);
		}
		catch (Exception e)
		{
			log.warn("Failed to parse emitter profiles", e);
			return null;
		}
	}

	@Nullable
	private Map<String, ProfileFolder> parseFolders(@Nullable String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, FOLDERS_TYPE);
		}
		catch (Exception e)
		{
			log.warn("Failed to parse profile folders", e);
			return null;
		}
	}

	@Nullable
	private static String loadBundledPresets()
	{
		return loadResource("/presets.json", "presets");
	}

	@Nullable
	private static String loadBundledFolders()
	{
		return loadResource("/folders.json", "folders");
	}

	@Nullable
	private static String loadResource(String path, String what)
	{
		try (InputStream in = EmitterStore.class.getResourceAsStream(path))
		{
			if (in == null)
			{
				return null;
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			log.warn("Failed to read bundled {}", what, e);
			return null;
		}
	}

	private void save()
	{
		configManager.setConfiguration(ParticlesConfig.GROUP, CONFIG_KEY, gson.toJson(profiles, MAP_TYPE));
		configManager.setConfiguration(ParticlesConfig.GROUP, FOLDERS_KEY, gson.toJson(folders, FOLDERS_TYPE));
		revision++;
		if (changeListener != null)
		{
			changeListener.run();
		}
	}

	/**
	 * Bumped on every mutation; lets the client thread cheaply detect that
	 * emitters need re-resolving against the current model.
	 */
	synchronized int getRevision()
	{
		return revision;
	}

	/**
	 * @return the key of some existing profile for this signature, or a newly
	 * created one
	 */
	synchronized String ensureProfileFor(String signature, String defaultName)
	{
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			if (signature.equals(entry.getValue().getSignature())
				&& EmitterProfile.TARGET_PLAYER.equals(entry.getValue().getTargetType()))
			{
				return entry.getKey();
			}
		}
		String key = freeKey(signature);
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setSignature(signature);
		profiles.put(key, profile);
		save();
		return key;
	}

	/**
	 * Clone a profile (vertices, style, filter) under a new key, e.g. to give
	 * another item variant of the same mesh its own particles.
	 *
	 * @return the new profile's key, or null
	 */
	@Nullable
	synchronized String duplicate(String profileKey)
	{
		EmitterProfile source = profiles.get(profileKey);
		if (source == null)
		{
			return null;
		}
		EmitterProfile copy = source.copy();
		copy.setName(source.getName() + " copy");
		String base = source.isProjectileTarget()
			? "proj:" + source.getProjectileId()
			: source.isGraphicTarget()
			? "gfx:" + source.getGraphicId()
			: source.getSignature();
		String key = freeKey(base);
		profiles.put(key, copy);
		save();
		return key;
	}

	/**
	 * @return the key of an existing object profile for this piece signature
	 * on this object ID, or a newly created one
	 */
	synchronized String ensureObjectPieceProfile(String signature, String defaultName, int objectId)
	{
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.isObjectTarget() && profile.getObjectId() == objectId
				&& signature.equals(profile.getSignature()))
			{
				return entry.getKey();
			}
		}
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setTargetType(EmitterProfile.TARGET_OBJECT);
		profile.setSignature(signature);
		profile.setObjectId(objectId);
		String key = freeKey(signature + "@obj" + objectId);
		profiles.put(key, profile);
		save();
		return key;
	}

	/**
	 * @return the key of an existing NPC profile for this piece signature on
	 * this NPC ID, or a newly created one
	 */
	synchronized String ensureNpcPieceProfile(String signature, String defaultName, int npcId)
	{
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.isNpcTarget() && profile.getNpcId() == npcId
				&& signature.equals(profile.getSignature()))
			{
				return entry.getKey();
			}
		}
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setTargetType(EmitterProfile.TARGET_NPC);
		profile.setSignature(signature);
		profile.setNpcId(npcId);
		String key = freeKey(signature + "@npc" + npcId);
		profiles.put(key, profile);
		save();
		return key;
	}

	/**
	 * The graphic profile for this piece signature on this spot anim ID. A
	 * point-based profile (no signature yet) for the same ID is upgraded in
	 * place rather than duplicated.
	 */
	synchronized String ensureGraphicPieceProfile(String signature, String defaultName, int graphicId)
	{
		String pointKey = null;
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (!profile.isGraphicTarget() || profile.getGraphicId() != graphicId)
			{
				continue;
			}
			if (signature.equals(profile.getSignature()))
			{
				return entry.getKey();
			}
			if (profile.getSignature() == null && pointKey == null)
			{
				pointKey = entry.getKey();
			}
		}
		if (pointKey != null)
		{
			profiles.get(pointKey).setSignature(signature);
			save();
			return pointKey;
		}
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setTargetType(EmitterProfile.TARGET_GRAPHIC);
		profile.setGraphicId(graphicId);
		profile.setSignature(signature);
		String key = freeKey(signature + "@gfx" + graphicId);
		profiles.put(key, profile);
		save();
		return key;
	}

	/**
	 * @return the key of an existing graphic profile for this spot anim ID,
	 * or a newly created one
	 */
	synchronized String ensureGraphicProfile(int graphicId, String defaultName)
	{
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.isGraphicTarget() && profile.getGraphicId() == graphicId)
			{
				return entry.getKey();
			}
		}
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setTargetType(EmitterProfile.TARGET_GRAPHIC);
		profile.setGraphicId(graphicId);
		profile.setRiseSpeed(20);
		String key = freeKey("gfx:" + graphicId);
		profiles.put(key, profile);
		save();
		return key;
	}

	/**
	 * @return the key of an existing profile for this projectile ID, or a
	 * newly created one with trail-friendly defaults
	 */
	synchronized String ensureProjectileProfile(int projectileId, String defaultName)
	{
		for (Map.Entry<String, EmitterProfile> entry : profiles.entrySet())
		{
			EmitterProfile profile = entry.getValue();
			if (profile.isProjectileTarget() && profile.getProjectileId() == projectileId)
			{
				return entry.getKey();
			}
		}
		EmitterProfile profile = new EmitterProfile(defaultName);
		profile.setTargetType(EmitterProfile.TARGET_PROJECTILE);
		profile.setProjectileId(projectileId);
		// Trails are what projectile particles are usually for
		profile.setTrailDensity(40);
		profile.setRiseSpeed(0);
		profile.setSpreadSpeed(4);
		String key = freeKey("proj:" + projectileId);
		profiles.put(key, profile);
		save();
		return key;
	}

	private String freeKey(String signature)
	{
		String key = signature;
		int n = 2;
		while (profiles.containsKey(key))
		{
			key = signature + "#" + n++;
		}
		return key;
	}

	/**
	 * @return a copy of the piece-local vertex set of a profile
	 */
	synchronized Set<Integer> vertexSet(String profileKey)
	{
		EmitterProfile profile = profiles.get(profileKey);
		return profile == null ? Set.of() : Set.copyOf(profile.getVertices());
	}

	/**
	 * Add or remove a piece-local vertex on an existing profile.
	 */
	synchronized void toggleVertex(String profileKey, int localVertex)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile == null)
		{
			return;
		}
		if (!profile.getVertices().remove(localVertex))
		{
			profile.getVertices().add(localVertex);
		}
		save();
	}

	/**
	 * Bulk-add piece-local vertices (box selection). Persists once.
	 */
	synchronized void addVertices(String profileKey, Collection<Integer> localVertices)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null && profile.getVertices().addAll(localVertices))
		{
			save();
		}
	}

	/**
	 * Bulk-remove piece-local vertices (box selection). Persists once.
	 */
	synchronized void removeVertices(String profileKey, Collection<Integer> localVertices)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null && profile.getVertices().removeAll(localVertices))
		{
			save();
		}
	}

	/**
	 * Copy the editable settings (style and item variant filter) into a profile.
	 */
	synchronized void updateStyle(String profileKey, EmitterProfile settingsSource)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null)
		{
			profile.copyStyleFrom(settingsSource);
			save();
		}
	}

	/**
	 * Re-attach a profile to a different mesh piece, keeping its style, name
	 * and item filter but clearing its vertices (local indices are meaningless
	 * on another piece). Recovery path for profiles orphaned by signature
	 * changes, and for copying a style setup onto new gear.
	 */
	synchronized void rebind(String profileKey, String newSignature)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile == null || newSignature.equals(profile.getSignature()))
		{
			return;
		}
		profile.setSignature(newSignature);
		profile.getVertices().clear();
		save();
	}

	synchronized void rename(String profileKey, String name)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null && name != null && !name.trim().isEmpty())
		{
			profile.setName(name.trim());
			save();
		}
	}

	synchronized void setEnabled(String profileKey, boolean enabled)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null && profile.isEnabled() != enabled)
		{
			profile.setEnabled(enabled);
			save();
		}
	}

	/**
	 * Mark a profile work-in-progress (or ship-ready), a developer-only flag
	 * that hides and force-disables it for shipped users. Persisted so it ships
	 * to presets.json.
	 */
	synchronized void setWip(String profileKey, boolean wip)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null && profile.isWip() != wip)
		{
			profile.setWip(wip);
			save();
		}
	}

	/**
	 * Overwrite a profile's editable style with another profile's, for the
	 * sidebar copy/paste flow.
	 */
	synchronized void pasteStyle(String profileKey, EmitterProfile source)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile != null)
		{
			profile.copyStyleFrom(source);
			save();
		}
	}

	synchronized void delete(String profileKey)
	{
		EmitterProfile removed = profiles.remove(profileKey);
		if (removed != null)
		{
			if (removed.getFolderId() != null)
			{
				autoDissolve(removed.getFolderId());
			}
			save();
		}
	}

	/**
	 * @return a deep copy of all profiles by key, for the non-gating lookups
	 * (rename/edit dialogs, worn-model scans) that only need profiles
	 */
	synchronized Map<String, EmitterProfile> snapshotAll()
	{
		Map<String, EmitterProfile> copy = new LinkedHashMap<>();
		profiles.forEach((k, v) -> copy.put(k, v.copy()));
		return copy;
	}

	/**
	 * @return an atomic deep copy of both maps, for the emission gates and the
	 * sidebar - so a profile is always scored against a coherent folder view
	 */
	synchronized Snapshot snapshot()
	{
		Map<String, EmitterProfile> p = new LinkedHashMap<>();
		profiles.forEach((k, v) -> p.put(k, v.copy()));
		Map<String, ProfileFolder> f = new LinkedHashMap<>();
		folders.forEach((k, v) -> f.put(k, v.copy()));
		return new Snapshot(p, f);
	}

	/**
	 * Developer helper: write the live profiles and folders out as the bundled
	 * presets.json and folders.json in a chosen directory, so the authoring
	 * config can be re-exported into the shipped pack in one click. Refuses to
	 * write (and reports why) if the folder invariant is violated, so a broken
	 * pair can never land. Returns a human summary for a dialog.
	 */
	synchronized String exportBundle(File dir) throws IOException
	{
		List<String> problems = new ArrayList<>();
		Map<String, Integer> counts = new HashMap<>();
		for (EmitterProfile profile : profiles.values())
		{
			String folderId = profile.getFolderId();
			if (folderId == null)
			{
				continue;
			}
			if (!folders.containsKey(folderId))
			{
				problems.add("profile \"" + profile.getName() + "\" points at missing folder " + folderId);
			}
			else
			{
				counts.merge(folderId, 1, Integer::sum);
			}
		}
		for (Map.Entry<String, ProfileFolder> entry : folders.entrySet())
		{
			int members = counts.getOrDefault(entry.getKey(), 0);
			if (members < 2)
			{
				problems.add("folder \"" + entry.getValue().getName() + "\" has " + members
					+ " member(s); needs at least 2");
			}
		}
		if (!problems.isEmpty())
		{
			return "Nothing written - fix these first:\n - " + String.join("\n - ", problems);
		}

		Files.write(new File(dir, "presets.json").toPath(),
			gson.toJson(profiles, MAP_TYPE).getBytes(StandardCharsets.UTF_8));
		Files.write(new File(dir, "folders.json").toPath(),
			gson.toJson(folders, FOLDERS_TYPE).getBytes(StandardCharsets.UTF_8));
		return "Wrote " + profiles.size() + " profiles and " + folders.size() + " folders to\n"
			+ dir.getAbsolutePath();
	}

	// --- Folders -------------------------------------------------------------

	/**
	 * Group two profiles: if the target is already in a folder the member joins
	 * it, otherwise a new folder is created named after the target. Rejects a
	 * cross-category or self grouping. The member leaves any prior folder.
	 */
	synchronized void createFolder(String targetKey, String memberKey)
	{
		EmitterProfile target = profiles.get(targetKey);
		EmitterProfile member = profiles.get(memberKey);
		if (target == null || member == null || targetKey.equals(memberKey)
			|| !sameCategory(target, member))
		{
			return;
		}
		String folderId = target.getFolderId();
		if (folderId == null)
		{
			folderId = freeFolderId();
			folders.put(folderId, new ProfileFolder(folderId, target.getName()));
			target.setFolderId(folderId);
		}
		moveToFolder(member, folderId);
		save();
	}

	/**
	 * Add a profile to an existing folder (dropping onto its header or a child),
	 * rejecting a cross-category join. The member leaves any prior folder.
	 */
	synchronized void addToFolder(String folderId, String memberKey)
	{
		ProfileFolder folder = folders.get(folderId);
		EmitterProfile member = profiles.get(memberKey);
		if (folder == null || member == null || folderId.equals(member.getFolderId()))
		{
			return;
		}
		EmitterProfile reference = anyMember(folderId);
		if (reference != null && !sameCategory(reference, member))
		{
			return;
		}
		moveToFolder(member, folderId);
		save();
	}

	/**
	 * Orphan one profile back to a loose row; dissolves the folder if it falls
	 * below two members.
	 */
	synchronized void removeFromFolder(String profileKey)
	{
		EmitterProfile profile = profiles.get(profileKey);
		if (profile == null || profile.getFolderId() == null)
		{
			return;
		}
		String folderId = profile.getFolderId();
		profile.setFolderId(null);
		autoDissolve(folderId);
		save();
	}

	/**
	 * Remove a folder, orphaning every member back to a loose row.
	 */
	synchronized void dissolveFolder(String folderId)
	{
		if (folders.remove(folderId) == null)
		{
			return;
		}
		for (EmitterProfile profile : profiles.values())
		{
			if (folderId.equals(profile.getFolderId()))
			{
				profile.setFolderId(null);
			}
		}
		save();
	}

	synchronized void setFolderEnabled(String folderId, boolean enabled)
	{
		ProfileFolder folder = folders.get(folderId);
		if (folder != null && folder.isEnabled() != enabled)
		{
			folder.setEnabled(enabled);
			save();
		}
	}

	synchronized void setFolderWip(String folderId, boolean wip)
	{
		ProfileFolder folder = folders.get(folderId);
		if (folder != null && folder.isWip() != wip)
		{
			folder.setWip(wip);
			save();
		}
	}

	synchronized void renameFolder(String folderId, String name)
	{
		ProfileFolder folder = folders.get(folderId);
		if (folder != null && name != null && !name.trim().isEmpty())
		{
			folder.setName(name.trim());
			save();
		}
	}

	/**
	 * Bulk enable/disable the rendered rows in one write: folder preferences for
	 * folders and profile toggles for loose profiles. Foldered children are
	 * never touched - users control the folder, not the child.
	 */
	synchronized void setEnabledMany(Collection<String> looseProfileKeys,
		Collection<String> folderIds, boolean enabled)
	{
		boolean changed = false;
		for (String key : looseProfileKeys)
		{
			EmitterProfile profile = profiles.get(key);
			if (profile != null && profile.isEnabled() != enabled)
			{
				profile.setEnabled(enabled);
				changed = true;
			}
		}
		for (String id : folderIds)
		{
			ProfileFolder folder = folders.get(id);
			if (folder != null && folder.isEnabled() != enabled)
			{
				folder.setEnabled(enabled);
				changed = true;
			}
		}
		if (changed)
		{
			save();
		}
	}

	private void moveToFolder(EmitterProfile member, String folderId)
	{
		String old = member.getFolderId();
		member.setFolderId(folderId);
		if (old != null && !old.equals(folderId))
		{
			autoDissolve(old);
		}
	}

	/**
	 * Dissolve a folder that has dropped below two members, orphaning any lone
	 * remaining member. Mutates without saving; the caller persists.
	 */
	private void autoDissolve(String folderId)
	{
		int count = 0;
		for (EmitterProfile profile : profiles.values())
		{
			if (folderId.equals(profile.getFolderId()))
			{
				count++;
			}
		}
		if (count < 2)
		{
			folders.remove(folderId);
			for (EmitterProfile profile : profiles.values())
			{
				if (folderId.equals(profile.getFolderId()))
				{
					profile.setFolderId(null);
				}
			}
		}
	}

	@Nullable
	private EmitterProfile anyMember(String folderId)
	{
		for (EmitterProfile profile : profiles.values())
		{
			if (folderId.equals(profile.getFolderId()))
			{
				return profile;
			}
		}
		return null;
	}

	private static boolean sameCategory(EmitterProfile a, EmitterProfile b)
	{
		return Objects.equals(a.getTargetType(), b.getTargetType());
	}

	private String freeFolderId()
	{
		int n = 1;
		while (folders.containsKey("folder:" + n))
		{
			n++;
		}
		return "folder:" + n;
	}
}

package dev.cnnnr;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Model;

/**
 * An immutable copy of a posed model's geometry, decomposed into connected
 * mesh pieces (groups of faces that share edges). Vertex indices match the
 * live model, so a vertex picked here can be used directly as an emitter anchor.
 *
 * Each piece carries a topology signature that is stable across model
 * recomposition: when equipment changes, a piece's global vertex indices shift
 * but its internal structure does not, so the signature (face wiring expressed
 * in piece-local vertex ranks) re-identifies the same piece in the new
 * composite. Emitters are stored per signature with piece-local indices and
 * mapped back to global indices against whatever model is currently worn.
 */
@Getter
class ModelSnapshot
{
	private final int vertexCount;
	private final int faceCount;
	private final float[] verticesX;
	private final float[] verticesY;
	private final float[] verticesZ;
	private final int[] faceIndices1;
	private final int[] faceIndices2;
	private final int[] faceIndices3;
	private final List<Piece> pieces;

	/**
	 * Piece index per vertex, -1 for vertices not referenced by any face.
	 */
	private final int[] vertexToPiece;

	@Getter
	static class Piece
	{
		private final String signature;
		private final int[] faces;
		/**
		 * Global vertex indices in first-appearance order over the piece's face
		 * stream; the position of a vertex in this array is its piece-local
		 * index. Appearance order (unlike global index order) is unaffected by
		 * the engine welding a vertex into another model's index range, so
		 * local indices and signatures survive e.g. head models touching the
		 * cape when a face-revealing helmet is worn.
		 */
		private final int[] vertices;
		/**
		 * Signatures this piece would produce under the three reversed-winding
		 * visit orders. A mirrored placement of the same mesh (some wall
		 * orientations flip the model, reversing triangle winding) hashes as
		 * one of these, so a profile authored on either handedness matches
		 * both. Field-confirmed 2026-07: same-ID wall torches produced 9v8f
		 * pieces with different hashes per orientation.
		 */
		private final String[] mirrorSignatures;
		/**
		 * First-appearance vertex orders for each mirror variant, so a
		 * profile matched through a mirror signature maps its piece-local
		 * indices onto the mirrored counterpart vertices.
		 */
		private final int[][] mirrorVertices;
		// Lookup: sorted globals with their parallel local indices
		private final int[] sortedVertices;
		private final int[] sortedToLocal;

		Piece(String signature, int[] faces, int[] vertices, String[] mirrorSignatures, int[][] mirrorVertices)
		{
			this.signature = signature;
			this.faces = faces;
			this.vertices = vertices;
			this.mirrorSignatures = mirrorSignatures;
			this.mirrorVertices = mirrorVertices;

			sortedVertices = vertices.clone();
			Arrays.sort(sortedVertices);
			sortedToLocal = new int[vertices.length];
			for (int local = 0; local < vertices.length; local++)
			{
				sortedToLocal[Arrays.binarySearch(sortedVertices, vertices[local])] = local;
			}
		}

		/**
		 * @return the piece-local index of a global vertex, or -1
		 */
		int localIndexOf(int globalVertex)
		{
			int pos = Arrays.binarySearch(sortedVertices, globalVertex);
			return pos < 0 ? -1 : sortedToLocal[pos];
		}

		/**
		 * Does this signature identify the piece, in either handedness?
		 */
		boolean matchesSignature(String sig)
		{
			if (signature.equals(sig))
			{
				return true;
			}
			for (String mirror : mirrorSignatures)
			{
				if (mirror.equals(sig))
				{
					return true;
				}
			}
			return false;
		}

		/**
		 * The local-to-global vertex order under whichever labeling produced
		 * this signature; the direct order when it isn't a mirror match.
		 */
		int[] verticesFor(String sig)
		{
			if (signature.equals(sig))
			{
				return vertices;
			}
			for (int m = 0; m < mirrorSignatures.length; m++)
			{
				if (mirrorSignatures[m].equals(sig))
				{
					return mirrorVertices[m];
				}
			}
			return vertices;
		}
	}

	/**
	 * Copy geometry from a model. Must be called on the client thread; the
	 * resulting snapshot is immutable and safe to hand to the Swing EDT.
	 */
	static ModelSnapshot capture(Model model)
	{
		return new ModelSnapshot(
			model.getVerticesCount(),
			model.getFaceCount(),
			model.getVerticesX().clone(),
			model.getVerticesY().clone(),
			model.getVerticesZ().clone(),
			model.getFaceIndices1().clone(),
			model.getFaceIndices2().clone(),
			model.getFaceIndices3().clone());
	}

	private ModelSnapshot(int vertexCount, int faceCount,
		float[] verticesX, float[] verticesY, float[] verticesZ,
		int[] faceIndices1, int[] faceIndices2, int[] faceIndices3)
	{
		this.vertexCount = vertexCount;
		this.faceCount = faceCount;
		this.verticesX = verticesX;
		this.verticesY = verticesY;
		this.verticesZ = verticesZ;
		this.faceIndices1 = faceIndices1;
		this.faceIndices2 = faceIndices2;
		this.faceIndices3 = faceIndices3;
		this.vertexToPiece = new int[vertexCount];
		this.pieces = decompose();
	}

	/**
	 * @return the piece a vertex belongs to, or null
	 */
	Piece pieceContaining(int vertex)
	{
		if (vertex < 0 || vertex >= vertexCount || vertexToPiece[vertex] < 0)
		{
			return null;
		}
		return pieces.get(vertexToPiece[vertex]);
	}

	/**
	 * Union-find over faces joined by shared edges, yielding connected
	 * components. Edge (not vertex) connectivity matters: the engine welds
	 * identical-position vertices of different equipment models together, so
	 * a single touching point (e.g. a face-revealing helmet's head model
	 * against the cape) would otherwise fuse separate pieces into one.
	 */
	private List<Piece> decompose()
	{
		int[] parent = new int[faceCount];
		for (int i = 0; i < faceCount; i++)
		{
			parent[i] = i;
		}

		Map<Long, Integer> edgeToFace = new HashMap<>(faceCount * 2);
		for (int f = 0; f < faceCount; f++)
		{
			unionEdge(edgeToFace, parent, f, faceIndices1[f], faceIndices2[f]);
			unionEdge(edgeToFace, parent, f, faceIndices2[f], faceIndices3[f]);
			unionEdge(edgeToFace, parent, f, faceIndices1[f], faceIndices3[f]);
		}

		// Group faces by component root, in ascending face order
		Map<Integer, List<Integer>> facesByRoot = new HashMap<>();
		for (int f = 0; f < faceCount; f++)
		{
			facesByRoot.computeIfAbsent(find(parent, f), k -> new ArrayList<>()).add(f);
		}

		// Piece-local vertex labels by first appearance in the face stream;
		// stamp marks which piece a label belongs to so the arrays are shared
		int[] label = new int[vertexCount];
		int[] stamp = new int[vertexCount];
		int stampValue = 0;

		List<Piece> result = new ArrayList<>();
		for (Map.Entry<Integer, List<Integer>> entry : facesByRoot.entrySet())
		{
			int[] faces = entry.getValue().stream().mapToInt(Integer::intValue).toArray();
			stampValue++;

			List<Integer> appearance = new ArrayList<>();
			long hash = hashPass(faces, faceIndices1, faceIndices2, faceIndices3,
				label, stamp, stampValue, appearance);
			int[] verts = appearance.stream().mapToInt(Integer::intValue).toArray();
			String signature = verts.length + "v" + faces.length + "f-" + Long.toHexString(hash);

			// The three reversed-winding visit orders: a mirrored placement
			// of this mesh hashes as one of them (which one depends on the
			// index pair the engine swaps when flipping)
			String[] mirrorSignatures = new String[3];
			int[][] mirrorVertices = new int[3][];
			for (int m = 0; m < 3; m++)
			{
				int[] o1 = m == 0 ? faceIndices1 : m == 1 ? faceIndices3 : faceIndices2;
				int[] o2 = m == 0 ? faceIndices3 : m == 1 ? faceIndices2 : faceIndices1;
				int[] o3 = m == 0 ? faceIndices2 : m == 1 ? faceIndices1 : faceIndices3;
				stampValue++;
				List<Integer> mirrorAppearance = new ArrayList<>();
				long mirrorHash = hashPass(faces, o1, o2, o3, label, stamp, stampValue, mirrorAppearance);
				mirrorVertices[m] = mirrorAppearance.stream().mapToInt(Integer::intValue).toArray();
				mirrorSignatures[m] = mirrorVertices[m].length + "v" + faces.length + "f-"
					+ Long.toHexString(mirrorHash);
			}

			result.add(new Piece(signature, faces, verts, mirrorSignatures, mirrorVertices));
		}
		result.sort(Comparator.comparingInt((Piece p) -> p.faces.length).reversed());

		// A welded vertex can belong to several pieces; the first (largest)
		// piece claims it for click mapping
		Arrays.fill(vertexToPiece, -1);
		for (int i = 0; i < result.size(); i++)
		{
			for (int v : result.get(i).vertices)
			{
				if (vertexToPiece[v] == -1)
				{
					vertexToPiece[v] = i;
				}
			}
		}
		return result;
	}

	private static long hashPass(int[] faces, int[] order1, int[] order2, int[] order3,
		int[] label, int[] stamp, int stampValue, List<Integer> appearance)
	{
		long hash = 1125899906842597L;
		for (int f : faces)
		{
			hash = 31 * hash + labelOf(order1[f], label, stamp, stampValue, appearance);
			hash = 31 * hash + labelOf(order2[f], label, stamp, stampValue, appearance);
			hash = 31 * hash + labelOf(order3[f], label, stamp, stampValue, appearance);
		}
		return hash;
	}

	private static int labelOf(int vertex, int[] label, int[] stamp, int stampValue, List<Integer> appearance)
	{
		if (stamp[vertex] != stampValue)
		{
			stamp[vertex] = stampValue;
			label[vertex] = appearance.size();
			appearance.add(vertex);
		}
		return label[vertex];
	}

	private static void unionEdge(Map<Long, Integer> edgeToFace, int[] parent, int face, int a, int b)
	{
		long key = a < b ? ((long) a << 32) | b : ((long) b << 32) | a;
		Integer other = edgeToFace.putIfAbsent(key, face);
		if (other != null)
		{
			union(parent, face, other);
		}
	}

	private static int find(int[] parent, int i)
	{
		int root = i;
		while (parent[root] != root)
		{
			root = parent[root];
		}
		// Path compression
		while (parent[i] != root)
		{
			int next = parent[i];
			parent[i] = root;
			i = next;
		}
		return root;
	}

	private static void union(int[] parent, int a, int b)
	{
		parent[find(parent, a)] = find(parent, b);
	}
}

package dev.cnnnr;

import lombok.Getter;
import lombok.Setter;

/**
 * A named group of emitter profiles shown as one collapsible row in the
 * sidebar. Its own enable and work-in-progress flags override those of its
 * member profiles, so end users control a whole multi-layer effect with a
 * single toggle. Membership lives on the profiles ({@link EmitterProfile#folderId});
 * this holds only the folder's own settings. Folders are single-category and
 * never nested, and always hold at least two members (enforced by the store).
 */
@Getter
@Setter
class ProfileFolder
{
	/**
	 * Stable generated id that member profiles reference by their folderId.
	 */
	private String id;
	/**
	 * Display name; adopts the target profile's name when the folder is created.
	 */
	private String name;
	/**
	 * Preference toggle. For shipped users this is the one folder setting they
	 * control, and it gates every member (a member emits only if both the folder
	 * and the member are enabled).
	 */
	private boolean enabled = true;
	/**
	 * Author's work-in-progress mark: hides and force-disables the whole folder
	 * for shipped users, taking priority over member settings.
	 */
	private boolean wip = false;

	ProfileFolder()
	{
	}

	ProfileFolder(String id, String name)
	{
		this.id = id;
		this.name = name;
	}

	ProfileFolder copy()
	{
		ProfileFolder c = new ProfileFolder(id, name);
		c.enabled = enabled;
		c.wip = wip;
		return c;
	}
}

package dev.cnnnr;

import lombok.Getter;

/**
 * A single particle in local scene coordinates (128 units per tile).
 * z is the absolute scene height (negative up), anchored to the player's base
 * height at spawn so particles stay glued to the model on uneven ground.
 * Purely simulation state; rendering is done by {@link ParticleRenderer}
 * batching live particles into per-tile models.
 *
 * Instances are pooled by {@link ParticleSystem} and reinitialized via
 * {@link #reset}, so fields are mutable by design.
 */
class Particle
{
	@Getter
	private float x;
	@Getter
	private float y;
	@Getter
	private float z;

	@Getter
	private float velX;
	@Getter
	private float velY;
	@Getter
	private float velZ;
	private float lifetime;
	// Sinusoidal drift so motion meanders instead of travelling straight
	private float wobblePhase;
	private float wobbleFreq;
	private float wobbleAmp;
	private float age;

	/**
	 * The style this particle renders with.
	 */
	@Getter
	private ParticleStyle style;

	/**
	 * Which pre-baked size variant of the style this particle renders with.
	 */
	@Getter
	private int sizeVariant;

	/**
	 * Per-particle uniform size scale from the profile's size jitter (1 = the
	 * base size), applied on top of the {@link #sizeVariant} auto-variation.
	 */
	@Getter
	private float sizeScale;

	void reset(float x, float y, float z, float velX, float velY, float velZ,
		float lifetime, ParticleStyle style, int sizeVariant, float sizeScale,
		float wobblePhase, float wobbleFreq, float wobbleAmp)
	{
		this.x = x;
		this.y = y;
		this.z = z;
		this.velX = velX;
		this.velY = velY;
		this.velZ = velZ;
		this.lifetime = lifetime;
		this.style = style;
		this.sizeVariant = sizeVariant;
		this.sizeScale = sizeScale;
		this.wobblePhase = wobblePhase;
		this.wobbleFreq = wobbleFreq;
		this.wobbleAmp = wobbleAmp;
		this.age = 0;
	}

	void update(float dt)
	{
		age += dt;
		// Gravity: downward acceleration on the vertical velocity (scene z is
		// negative-up, so falling means an increasing z). Constant when 0.
		velZ += style.getGravity() * dt;
		// Drag: shed a fraction of the particle's own velocity so rises,
		// spreads and falls settle over life. With gravity this converges on a
		// terminal fall speed. Wind (below) is a separate steady drift and is
		// not decayed - it is the medium moving, not the particle's momentum.
		float drag = style.getDragPerSec();
		if (drag > 0f)
		{
			float keep = Math.max(0f, 1f - drag * dt);
			velX *= keep;
			velY *= keep;
			velZ *= keep;
		}
		float t = age * wobbleFreq + wobblePhase;
		x += (velX + style.getWindX() + (float) Math.sin(t) * wobbleAmp) * dt;
		y += (velY + style.getWindY() + (float) Math.cos(t * 1.3f) * wobbleAmp) * dt;
		// Wind Z is up-positive like Rise; scene z is negative-up, so subtract.
		z += (velZ - style.getWindZ()) * dt;
	}

	boolean isDead()
	{
		return age >= lifetime;
	}

	void kill()
	{
		age = lifetime;
	}

	/**
	 * @return remaining life as 1 (just spawned) to 0 (dead)
	 */
	float lifeFraction()
	{
		return Math.max(0f, 1f - age / lifetime);
	}
}

package dev.cnnnr;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Debug overlay: marks the active emitter vertices in-game.
 * Particles themselves are rendered as scene objects by {@link ParticleRenderer}.
 */
class ParticlesOverlay extends Overlay
{
	private static final Color MARKER = new Color(0, 220, 255, 200);

	private final Client client;
	private final ParticlesPlugin plugin;
	private final ParticlesConfig config;

	@Inject
	ParticlesOverlay(Client client, ParticlesPlugin plugin, ParticlesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showAnchor())
		{
			return null;
		}

		// Diagnostics: sim vs render state, for telling apart early particle
		// death (sim bug) from objects not being drawn (engine limitation)
		String stats = plugin.getStatsLine();
		if (!stats.isEmpty())
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(stats, 11, 41);
			graphics.setColor(Color.CYAN);
			graphics.drawString(stats, 10, 40);
		}

		// Stack-winner oracle for the hovered tile (developer mode only)
		String oracle = plugin.getOracleLine();
		if (!oracle.isEmpty())
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(oracle, 11, 56);
			graphics.setColor(Color.ORANGE);
			graphics.drawString(oracle, 10, 55);
		}

		// NPC stacked-draw oracle, one line below
		String npcOracle = plugin.getNpcOracleLine();
		if (!npcOracle.isEmpty())
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(npcOracle, 11, 71);
			graphics.setColor(Color.ORANGE);
			graphics.drawString(npcOracle, 10, 70);
		}

		if (plugin.getAnchorCount() == 0)
		{
			return null;
		}

		graphics.setColor(MARKER);
		for (int i = 0; i < plugin.getAnchorCount(); i++)
		{
			// Anchor z is absolute scene height, so project it directly rather
			// than letting localToCanvas re-derive height from the terrain
			// under the anchor - that desyncs from the model on slopes
			Point canvas = Perspective.localToCanvas(client,
				plugin.getAnchorWorldView(),
				(int) plugin.getAnchorXs()[i],
				(int) plugin.getAnchorYs()[i],
				(int) plugin.getAnchorZs()[i]);
			if (canvas == null)
			{
				continue;
			}
			graphics.drawOval(canvas.getX() - 3, canvas.getY() - 3, 6, 6);
		}

		// The feathered emission line, for tuning feather strength
		for (float[] points : plugin.getFeatherDebugPaths())
		{
			Point previous = null;
			for (int i = 0; i < points.length; i += 3)
			{
				Point current = Perspective.localToCanvas(client,
					plugin.getAnchorWorldView(),
					(int) points[i], (int) points[i + 1], (int) points[i + 2]);
				if (previous != null && current != null)
				{
					graphics.drawLine(previous.getX(), previous.getY(), current.getX(), current.getY());
				}
				previous = current;
			}
		}

		return null;
	}
}

package dev.cnnnr;

import java.util.Set;
import lombok.Getter;
import net.runelite.api.ModelData;

/**
 * Resolved runtime style for one emitter piece: pre-baked disc templates for
 * every (size variant, fade step) plus the emission parameters. Built by
 * {@link ParticleRenderer} from an {@link EmitterProfile}; immutable once built.
 */
@Getter
class ParticleStyle
{
	static final int FADE_STEPS = 12;
	/**
	 * Per-particle random size multipliers; this fixed spread makes the cloud
	 * read as organic instead of uniform beads. The profile's size jitter is a
	 * separate, per-particle scaling of the base that rides on top of these.
	 */
	static final float[] SIZE_MULTIPLIERS = {0.65f, 1.0f, 1.4f};
	/**
	 * The lowest particle size we allow; also the floor of the jitter range.
	 */
	static final int MIN_SIZE = 2;

	/**
	 * Unlit disc templates indexed [size variant][fade step], facing +z,
	 * centered on the origin.
	 */
	private final ModelData[][] templates;
	/**
	 * Pre-lit per-face colors indexed [fade step], copied into batch canvases
	 * in place of per-tick relighting. Colour is constant across a particle's
	 * life unless a colour gradient is set, so without one every fade step
	 * holds the same array and the batch copies it just once per style.
	 */
	private final int[][] litColors1;
	private final int[][] litColors2;
	private final int[][] litColors3;
	/**
	 * The colour changes over life (end colour differs from start), so the
	 * batch must recopy the lit colours each fade step, not once per style.
	 */
	private final boolean colorGradient;
	private final float lifetimeSec;
	private final float particlesPerSecond;
	/**
	 * Particles per tile of anchor movement; 0 = off. See EmitterProfile.
	 */
	private final float trailDensity;
	private final float riseSpeed;
	private final float spreadSpeed;
	/**
	 * Per-particle random size spread around the base, in local units; 0 = every
	 * particle the base size. Realized as a per-particle scale at spawn, on top
	 * of the fixed {@link #SIZE_MULTIPLIERS} auto-variation. See EmitterProfile.
	 */
	private final int sizeJitter;
	/**
	 * Downward acceleration in local units per second squared; see
	 * EmitterProfile.
	 */
	private final float gravity;
	/**
	 * Steady world-aligned wind drift in local units per second (X east,
	 * Y north, Z up); see EmitterProfile.
	 */
	private final float windX;
	private final float windY;
	private final float windZ;
	/**
	 * Fraction of a particle's own velocity shed per second (0 = none); see
	 * EmitterProfile.
	 */
	private final float dragPerSec;
	/**
	 * Radial spawn velocity from the emitter centroid, outward (+) / inward (-),
	 * local units per second; see EmitterProfile.
	 */
	private final float vortex;
	/**
	 * Emit-point scale about the centroid as a multiplier (1 = unchanged); see
	 * EmitterProfile.
	 */
	private final float emitScale;
	/**
	 * Billboard elongation factor along screen velocity (1 = round); see
	 * EmitterProfile.
	 */
	private final float stretchFactor;
	/**
	 * Life fraction at which stretch begins as a multiplier (1 = full stretch
	 * from spawn, 0 = starts round and ramps up over life). See EmitterProfile.
	 */
	private final float stretchRampStart;
	/**
	 * The profile's base diameter; the renderer needs it to cap the stretch
	 * so an elongated billboard stays inside the batch bounds volume.
	 */
	private final int baseSize;
	private final float spawnJitter;
	private final int featherStrength;
	/**
	 * Midpoints inserted between mesh-adjacent emitter vertices;
	 * see EmitterProfile.
	 */
	private final int interpolation;
	/**
	 * Camera-ward render nudge in local units; see EmitterProfile.
	 */
	private final float depthBias;
	/**
	 * Lifetime multiplier while the wearer walks or runs; see EmitterProfile.
	 */
	private final float movementLifetimeScale;
	/**
	 * Fixed emit offset from the vertex in model space, applied before the
	 * player's facing rotation so it turns with them. X sideways, Y
	 * forward/back, Z up (positive).
	 */
	private final float offsetX;
	private final float offsetY;
	private final float offsetZ;
	private final Set<Integer> animationIds;
	/**
	 * Flattened [start0, end0, start1, end1, ...] frame windows for action
	 * animation matches, or null for all frames.
	 */
	private final int[] animFrameRanges;

	ParticleStyle(ModelData[][] templates, int[][] litColors1, int[][] litColors2, int[][] litColors3,
		EmitterProfile profile)
	{
		this.templates = templates;
		this.litColors1 = litColors1;
		this.litColors2 = litColors2;
		this.litColors3 = litColors3;
		this.colorGradient = profile.isColorFade() && profile.getColorEnd() != profile.getColor();
		this.lifetimeSec = profile.getLifetimeMs() / 1000f;
		this.particlesPerSecond = profile.getParticlesPerSecond();
		this.trailDensity = profile.getTrailDensity();
		this.riseSpeed = profile.getRiseSpeed();
		this.spreadSpeed = profile.getSpreadSpeed();
		this.sizeJitter = Math.max(0, profile.getSizeJitter());
		this.gravity = profile.getGravity();
		this.windX = profile.getWindX();
		this.windY = profile.getWindY();
		this.windZ = profile.getWindZ();
		this.dragPerSec = Math.max(0, profile.getDrag()) / 100f;
		this.vortex = profile.getVortex();
		this.emitScale = Math.max(0, profile.getEmitScale()) / 100f;
		this.stretchFactor = 1f + Math.max(0, profile.getStretch()) / 100f;
		this.stretchRampStart = 1f - Math.max(0, Math.min(100, profile.getStretchRamp())) / 100f;
		this.baseSize = profile.getSize();
		this.spawnJitter = profile.getSpawnJitter();
		this.featherStrength = profile.getFeatherStrength();
		this.interpolation = Math.max(0, Math.min(4, profile.getInterpolation()));
		this.depthBias = profile.getDepthBias();
		this.movementLifetimeScale = Math.max(10, Math.min(100, profile.getMovementLifetime())) / 100f;
		this.offsetX = profile.getOffsetX();
		this.offsetY = profile.getOffsetY();
		this.offsetZ = profile.getOffsetZ();
		this.animationIds = Set.copyOf(profile.getAnimationIds());
		this.animFrameRanges = parseFrameRanges(profile.getAnimFrames());
	}

	/**
	 * Parse "9-13, 15-19, 25" into flattened start/end pairs; single numbers
	 * become one-frame windows, junk tokens are ignored.
	 *
	 * @return null when no valid ranges (= all frames pass)
	 */
	private static int[] parseFrameRanges(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}
		java.util.List<Integer> bounds = new java.util.ArrayList<>();
		for (String token : text.split(","))
		{
			try
			{
				String[] parts = token.trim().split("-", 2);
				if (parts[0].isEmpty())
				{
					continue;
				}
				int start = Integer.parseInt(parts[0].trim());
				int end = parts.length > 1 ? Integer.parseInt(parts[1].trim()) : start;
				bounds.add(Math.min(start, end));
				bounds.add(Math.max(start, end));
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		if (bounds.isEmpty())
		{
			return null;
		}
		int[] ranges = new int[bounds.size()];
		for (int i = 0; i < ranges.length; i++)
		{
			ranges[i] = bounds.get(i);
		}
		return ranges;
	}

	/**
	 * The frame-window check alone, for spot anim gating where the graphic
	 * ID itself already gates. No windows = every frame passes.
	 */
	boolean frameMatches(int frame)
	{
		if (animFrameRanges == null)
		{
			return true;
		}
		for (int i = 0; i < animFrameRanges.length; i += 2)
		{
			if (frame >= animFrameRanges[i] && frame <= animFrameRanges[i + 1])
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Animation gate: emit only while the player's action or pose animation
	 * matches, with optional frame windows on action matches. An empty gate
	 * always passes; live particles are unaffected and fade out naturally.
	 */
	boolean animationMatches(int actionAnimation, int actionFrame, int poseAnimation)
	{
		if (animationIds.isEmpty())
		{
			return true;
		}
		if (animationIds.contains(actionAnimation))
		{
			if (animFrameRanges == null)
			{
				return true;
			}
			for (int i = 0; i < animFrameRanges.length; i += 2)
			{
				if (actionFrame >= animFrameRanges[i] && actionFrame <= animFrameRanges[i + 1])
				{
					return true;
				}
			}
			return false;
		}
		return animationIds.contains(poseAnimation);
	}
}

